func decodeStateDomainChangeBinaryAccessorKey(key []byte, change *rawdb.StateDomainChange) error {
	if change == nil || len(key) < 1+common.AccountIDLength {
		return errors.New("snapshots: invalid V6 logical key")
	}
	flat := rawdb.StateFlatDomain(key[0])
	if flat != rawdb.StateFlatDomainAccountLatest && flat != rawdb.StateFlatDomainKVLatest && flat != rawdb.StateFlatDomainKVGeneration {
		return errors.New("snapshots: invalid V6 flat domain")
	}
	change.FlatDomain = flat
	var id common.AccountID
	copy(id[:], key[1:1+common.AccountIDLength])
	change.Owner = id.Address(common.AddressPrefixMainnet)
	rest := key[1+common.AccountIDLength:]
	if flat == rawdb.StateFlatDomainKVLatest {
		if len(rest) < 10 {
			return errors.New("snapshots: invalid V6 KV logical key")
		}
		change.Generation = binary.BigEndian.Uint64(rest[:8])
		change.Domain = kvdomains.KVDomain(binary.BigEndian.Uint16(rest[8:10]))
		change.Key = append(change.Key[:0], rest[10:]...)
	} else if len(rest) != 0 {
		return errors.New("snapshots: V6 account/generation key has trailing bytes")
	}
	return nil
}

func encodeStateDomainChangeRecordV6(change *rawdb.StateDomainChange, keyID uint32) ([]byte, error) {
	payloadSize, err := stateDomainChangeRecordV6PayloadSize(change)
	if err != nil {
		return nil, err
	}
	payload := make([]byte, payloadSize)
	putStateDomainChangeRecordV6(payload, change, keyID)
	return payload, nil
}

func stateDomainChangeRecordV6PayloadSize(change *rawdb.StateDomainChange) (int, error) {
	if change == nil || uint64(len(change.Prev)) > math.MaxUint32 {
		return 0, errors.New("snapshots: invalid V6 state-domain-change record")
	}
	return 4 + 8 + 1 + 4 + len(change.Prev), nil
}

// putStateDomainChangeRecordV6 encodes into exact-sized caller-owned storage.
// Callers validate the change and reserve stateDomainChangeRecordV6PayloadSize
// bytes first. Keeping this primitive allocation-free lets streaming snapshot
// writers reuse their record scratch buffer without a payload copy.
func putStateDomainChangeRecordV6(payload []byte, change *rawdb.StateDomainChange, keyID uint32) {
	binary.BigEndian.PutUint32(payload[:4], keyID)
	binary.BigEndian.PutUint64(payload[4:12], change.TxNum)
	if change.PrevExists {
		payload[12] = 1
	} else {
		payload[12] = 0
	}
	binary.BigEndian.PutUint32(payload[13:17], uint32(len(change.Prev)))
	copy(payload[17:], change.Prev)
}

func encodeStateDomainChangeBinarySegmentV6(fromTxNum, toTxNum uint64, changes []*rawdb.StateDomainChange, txRangeSets ...[]*rawdb.StateTxRange) ([]byte, []stateDomainChangeBinaryTxOffset, []byte, error) {
	if toTxNum < fromTxNum {
		return nil, nil, nil, fmt.Errorf("snapshots: state-domain-change range [%d,%d] is inverted", fromTxNum, toTxNum)
	}
	txRanges, err := normalizeStateTxRangesForBinary(fromTxNum, toTxNum, changes, firstStateTxRangeSet(txRangeSets))
	if err != nil {
		return nil, nil, nil, err
	}
	keySet := make(map[string]struct{})
	for _, change := range changes {
		keySet[string(stateDomainChangeBinaryAccessorKey(change))] = struct{}{}
	}
	keyStrings := make([]string, 0, len(keySet))
	for key := range keySet {
		keyStrings = append(keyStrings, key)
	}
	sort.Strings(keyStrings)
	keyIDs := make(map[string]uint32, len(keyStrings))
	dictionaryKeys := make([]stateDomainChangeBinaryAccessorV6Key, len(keyStrings))
	for i, key := range keyStrings {
		keyIDs[key] = uint32(i)
		dictionaryKeys[i] = stateDomainChangeBinaryAccessorV6Key{key: []byte(key)}
	}
	var buf bytes.Buffer
	writeStateDomainChangeBinaryHeaderVersion(&buf, stateDomainChangeBinarySegmentMagic, fromTxNum, toTxNum, uint64(len(changes)), stateDomainChangeBinaryVersionV6)
	dictionaryDigest := stateDomainChangeBinaryAccessorV6DictionaryDigest(dictionaryKeys)
	if err := writeStateDomainChangeBinaryV6DictionaryCommitment(&buf, dictionaryDigest); err != nil {
		return nil, nil, nil, err
	}
	if err := writeStateDomainChangeBinaryTxRangeTable(&buf, txRanges); err != nil {
		return nil, nil, nil, err
	}
	index := make([]stateDomainChangeBinaryTxOffset, 0)
	entries := make([]stateDomainChangeBinaryAccessorEntry, 0, len(changes))
	for i, change := range changes {
		if change.TxNum < fromTxNum || change.TxNum > toTxNum {
			return nil, nil, nil, fmt.Errorf("snapshots: V6 tx %d outside segment range", change.TxNum)
		}
		key := stateDomainChangeBinaryAccessorKey(change)
		payload, err := encodeStateDomainChangeRecordV6(change, keyIDs[string(key)])
		if err != nil {
			return nil, nil, nil, err
		}
		offset := uint64(buf.Len())
		writeUint32(&buf, uint32(len(payload)))
		buf.Write(payload)
		entries = append(entries, stateDomainChangeBinaryAccessorEntry{key: key, txNum: change.TxNum, seq: uint64(i) + 1, offset: offset, recordIndex: uint64(i)})
		if len(index) == 0 || index[len(index)-1].txNum != change.TxNum {
			index = append(index, stateDomainChangeBinaryTxOffset{txNum: change.TxNum, offset: offset, recordIndex: uint64(i), count: 1})
		} else {
			index[len(index)-1].count++
		}
	}
	accessor, recordIDs, err := encodeStateDomainChangeBinaryAccessorV6(fromTxNum, toTxNum, entries)
	if err != nil {
		return nil, nil, nil, err
	}
	for i, entry := range entries {
		if recordIDs[i] != keyIDs[string(entry.key)] {
			return nil, nil, nil, errors.New("snapshots: V6 key id assignment mismatch")
		}
	}
	return buf.Bytes(), index, accessor, nil
}

func decodeStateDomainChangeRecordV6(data []byte) (uint32, *rawdb.StateDomainChange, error) {
	change := new(rawdb.StateDomainChange)
	keyID, err := decodeStateDomainChangeRecordV6Into(data, change)
	if err != nil {
		return 0, nil, err
	}
	return keyID, change, nil
}

func decodeStateDomainChangeRecordV6Into(data []byte, change *rawdb.StateDomainChange) (uint32, error) {
	if change == nil {
		return 0, errors.New("snapshots: nil V6 state-domain-change destination")
	}
	if len(data) < 17 {
		return 0, io.ErrUnexpectedEOF
	}
	*change = rawdb.StateDomainChange{TxNum: binary.BigEndian.Uint64(data[4:12])}
	if data[12] > 1 {
		return 0, errors.New("snapshots: invalid V6 previous-value marker")
	}
	change.PrevExists = data[12] == 1
	length := uint64(binary.BigEndian.Uint32(data[13:17]))
	if length != uint64(len(data)-17) {
		return 0, errors.New("snapshots: invalid V6 previous-value length")
	}
	if length != 0 {
		change.Prev = data[17:]
	}
	return binary.BigEndian.Uint32(data[:4]), nil
}

package snapshots

import (
	"bufio"
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"hash/maphash"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"

	"github.com/ethereum/go-ethereum/ethdb"
	"github.com/tronprotocol/go-tron/core/rawdb"
	"github.com/tronprotocol/go-tron/core/rawdb/etl"
)

const stateDomainChangeV6DictionaryCacheBlocks = 64
const stateDomainChangeV6KeyTableMaxBytes = 512 << 20

// This is only an exact build-time prefilter. ETL remains authoritative for
// sorting and deduplicating keys across cache resets. Both owned key bytes and
// entry count are bounded; the Go map's metadata is additional to the byte cap.
const stateDomainChangeV6KeyDedupMaxBytes = 16 << 20
const stateDomainChangeV6KeyDedupMaxEntries = 1 << 16
const stateDomainChangeV6KeyDedupTrialKeys = 4096

type stateDomainChangeV6DictionaryBlock struct {
	firstKey []byte
	offset   uint64
	length   uint32
	count    uint32
}

type stateDomainChangeV6Build struct {
	opts              etl.Options
	keys              *etl.Collector
	postings          *etl.Collector
	dictionary        *os.File
	dictName          string
	blocks            []stateDomainChangeV6DictionaryBlock
	keyCount          uint32
	keyStats          etl.Stats
	cache             map[int][][]byte
	cacheOrder        []int
	keyScratch        []byte
	keyDedup          map[string]struct{}
	keyDedupBytes     int
	keyDedupTrial     int
	keyDedupTrialHits int
	keyDedupDisabled  bool
	keyTable          []byte
	keyMask           uint64
	keyHashSeed       maphash.Seed
	dictionaryDigest  [sha256.Size]byte
	offsets           *historyAccessorOffsetBuilder
}

func newStateDomainChangeV6Build(opts etl.Options, dir, base string) (*stateDomainChangeV6Build, error) {
	if opts.TempDir == "" {
		opts.TempDir = filepath.Join(dir, "etl")
	}
	keys, err := etl.NewCollector(opts)
	if err != nil {
		return nil, fmt.Errorf("snapshots: create V6 key ETL: %w", err)
	}
	postings, err := etl.NewCollector(opts)
	if err != nil {
		_ = keys.Close()
		return nil, fmt.Errorf("snapshots: create V6 posting ETL: %w", err)
	}
	dictionaryDir := filepath.Dir(filepath.Join(dir, base))
	if err := os.MkdirAll(dictionaryDir, 0o755); err != nil {
		_ = keys.Close()
		_ = postings.Close()
		return nil, err
	}
	dictionary, dictName, err := createStateDomainChangeBinaryTempFileInDir(dictionaryDir, filepath.Base(base)+".v6-dictionary")
	if err != nil {
		_ = keys.Close()
		_ = postings.Close()
		return nil, err
	}
	return &stateDomainChangeV6Build{
		opts: opts, keys: keys, postings: postings, dictionary: dictionary,
		dictName: dictName, cache: make(map[int][][]byte), keyHashSeed: maphash.MakeSeed(),
	}, nil
}

func (b *stateDomainChangeV6Build) Close() {
	if b == nil {
		return
	}
	b.offsets.Close()
	b.offsets = nil
	b.keyDedup = nil
	b.keyDedupBytes = 0
	if b.keys != nil {
		_ = b.keys.Close()
	}
	if b.postings != nil {
		_ = b.postings.Close()
	}
	if b.dictionary != nil {
		_ = b.dictionary.Close()
	}
	if b.dictName != "" {
		_ = os.Remove(b.dictName)
	}
}

func (b *stateDomainChangeV6Build) CollectKey(change *rawdb.StateDomainChange) error {
	if b == nil || b.keys == nil || change == nil {
		return errors.New("snapshots: nil V6 key collector/change")
	}
	b.keyScratch = appendStateDomainChangeBinaryAccessorLookupKey(b.keyScratch[:0], change.FlatDomain, change.Owner, change.Generation, change.Domain, change.Key)
	return b.CollectLogicalKey(b.keyScratch)
}

// CollectLogicalKey adds one already-encoded V6 dictionary key. V6-to-V6
// compaction walks each source dictionary once instead of resolving the same
// keyID for every posting in transaction order.
func (b *stateDomainChangeV6Build) CollectLogicalKey(logicalKey []byte) error {
	if b == nil || b.keys == nil || len(logicalKey) == 0 {
		return errors.New("snapshots: nil V6 key collector/logical key")
	}
	if len(logicalKey) > math.MaxUint16 {
		return fmt.Errorf("snapshots: V6 logical key length %d exceeds uint16", len(logicalKey))
	}
	if !b.keyDedupDisabled {
		if _, exists := b.keyDedup[string(logicalKey)]; exists {
			b.observeKeyDedup(true)
			return nil
		}
	}
	if err := b.keys.PutEncoded(len(logicalKey), 0, func(key, _ []byte) {
		copy(key, logicalKey)
	}); err != nil {
		return err
	}
	if b.keyDedupDisabled {
		return nil
	}
	b.observeKeyDedup(false)
	if b.keyDedupDisabled {
		return nil
	}
	// Cache only successfully accepted keys. In particular, a failed spill must
	// not cause a subsequent retry to skip a key which ETL did not accept.
	if b.keyDedup == nil {
		b.keyDedup = make(map[string]struct{})
	} else if len(b.keyDedup) >= stateDomainChangeV6KeyDedupMaxEntries || len(logicalKey) > stateDomainChangeV6KeyDedupMaxBytes-b.keyDedupBytes {
		clear(b.keyDedup)
		b.keyDedupBytes = 0
	}
	b.keyDedup[string(logicalKey)] = struct{}{}
	b.keyDedupBytes += len(logicalKey)
	return nil
}

func (b *stateDomainChangeV6Build) observeKeyDedup(hit bool) {
	if b.keyDedupTrial >= stateDomainChangeV6KeyDedupTrialKeys {
		return
	}
	b.keyDedupTrial++
	if hit {
		b.keyDedupTrialHits++
	}
	// Unique-heavy inputs should not pay for a second key copy and map
	// insertion for the entire segment. Keep the cache only if the initial
	// bounded trial avoided at least one ETL row per sixteen probes. This is an
	// efficiency decision; ETL still deduplicates every accepted input key.
	if b.keyDedupTrial == stateDomainChangeV6KeyDedupTrialKeys && b.keyDedupTrialHits*16 < b.keyDedupTrial {
		b.keyDedup = nil
		b.keyDedupBytes = 0
		b.keyDedupDisabled = true
	}
}

type stateDomainChangeV6DictionaryWriter struct {
	build    *stateDomainChangeV6Build
	block    [][]byte
	previous []byte
}

func (w *stateDomainChangeV6DictionaryWriter) Put(key, _ []byte) error {
	if w == nil || w.build == nil || w.build.dictionary == nil || len(key) == 0 {
		return errors.New("snapshots: invalid V6 dictionary key")
	}
	if w.previous != nil && bytes.Compare(w.previous, key) >= 0 {
		return errors.New("snapshots: V6 dictionary keys are not strictly ordered")
	}
	if w.build.keyCount == math.MaxUint32 {
		return errors.New("snapshots: V6 dictionary exceeds uint32 key IDs")
	}
	w.block = append(w.block, append([]byte(nil), key...))
	w.previous = append(w.previous[:0], key...)
	w.build.keyCount++
	if len(w.block) == stateDomainChangeBinaryAccessorV6BlockKeys {
		return w.flush()
	}
	return nil
}
func (*stateDomainChangeV6DictionaryWriter) Delete([]byte) error {
	return errors.New("snapshots: V6 dictionary delete")
}
func (w *stateDomainChangeV6DictionaryWriter) flush() error {
	if len(w.block) == 0 {
		return nil
	}
	off, err := w.build.dictionary.Seek(0, io.SeekCurrent)
	if err != nil {
		return err
	}
	raw := encodeStateDomainChangeV6DictionaryBlock(w.block)
	if _, err := w.build.dictionary.Write(raw); err != nil {
		return err
	}
	w.build.blocks = append(w.build.blocks, stateDomainChangeV6DictionaryBlock{firstKey: append([]byte(nil), w.block[0]...), offset: uint64(off), length: uint32(len(raw)), count: uint32(len(w.block))})
	w.block = w.block[:0]
	return nil
}

func encodeStateDomainChangeV6DictionaryBlock(keys [][]byte) []byte {
	var raw []byte
	var previous []byte
	for _, key := range keys {
		prefix := commonPrefixLength(previous, key)
		raw = binary.AppendUvarint(raw, uint64(prefix))
		raw = binary.AppendUvarint(raw, uint64(len(key)-prefix))
		raw = append(raw, key[prefix:]...)
		previous = key
	}
	return raw
}

func decodeStateDomainChangeV6DictionaryBlock(raw []byte, count uint32) ([][]byte, error) {
	reader := bytes.NewReader(raw)
	keys := make([][]byte, 0, count)
	var previous []byte
	for i := uint32(0); i < count; i++ {
		prefix, err := binary.ReadUvarint(reader)
		if err != nil || prefix > uint64(len(previous)) {
			return nil, errors.New("snapshots: invalid V6 dictionary prefix")
		}
		suffix, err := binary.ReadUvarint(reader)
		if err != nil || suffix > uint64(reader.Len()) {
			return nil, errors.New("snapshots: invalid V6 dictionary suffix")
		}
		key := make([]byte, prefix+suffix)
		copy(key, previous[:prefix])
		if _, err := io.ReadFull(reader, key[prefix:]); err != nil {
			return nil, err
		}
		if i > 0 && bytes.Compare(previous, key) >= 0 {
			return nil, errors.New("snapshots: unordered V6 dictionary block")
		}
		keys = append(keys, key)
		previous = key
	}
	if reader.Len() != 0 {
		return nil, errors.New("snapshots: V6 dictionary block trailing bytes")
	}
	return keys, nil
}

func (b *stateDomainChangeV6Build) FinishDictionary() error {
	return b.FinishDictionaryContext(context.Background())
}

func (b *stateDomainChangeV6Build) FinishDictionaryContext(ctx context.Context) error {
	if b == nil || b.keys == nil {
		return errors.New("snapshots: nil V6 dictionary build")
	}
	writer := &stateDomainChangeV6DictionaryWriter{build: b}
	stats, err := loadHistoryETLContext(ctx, b.keys, writer)
	if err != nil {
		return err
	}
	if err := writer.flush(); err != nil {
		return err
	}
	if err := b.dictionary.Sync(); err != nil {
		return err
	}
	b.keyStats = stats
	_ = b.keys.Close()
	b.keys = nil
	b.keyDedup = nil
	b.keyDedupBytes = 0
	return b.buildKeyTable(ctx)
}

func (b *stateDomainChangeV6Build) iterateDictionaryKeys(ctx context.Context, fn func(uint32, []byte) error) error {
	for blockIndex := range b.blocks {
		if err := contextError(ctx); err != nil {
			return err
		}
		keys, err := b.dictionaryBlock(blockIndex)
		if err != nil {
			return err
		}
		for i, key := range keys {
			if err := fn(uint32(blockIndex*stateDomainChangeBinaryAccessorV6BlockKeys+i), key); err != nil {
				return err
			}
		}
	}
	return nil
}

func (b *stateDomainChangeV6Build) buildKeyTable(ctx context.Context) error {
	if err := contextError(ctx); err != nil {
		return err
	}
	buckets := uint64(1)
	for buckets*7 < uint64(b.keyCount)*10 {
		buckets <<= 1
	}
	useTable := b.keyCount != 0 && buckets <= uint64(stateDomainChangeV6KeyTableMaxBytes/16)
	if useTable {
		b.keyTable = make([]byte, buckets*16)
		b.keyMask = buckets - 1
	}
	digest := sha256.New()
	var length [4]byte
	err := b.iterateDictionaryKeys(ctx, func(keyID uint32, key []byte) error {
		binary.BigEndian.PutUint32(length[:], uint32(len(key)))
		_, _ = digest.Write(length[:])
		_, _ = digest.Write(key)
		if !useTable {
			return nil
		}
		token := stateDomainChangeV6BuildKeyToken(b.keyHashSeed, key)
		slot := binary.LittleEndian.Uint64(token[:8]) & b.keyMask
		for probes := uint64(0); probes <= b.keyMask; probes++ {
			off := slot * 16
			id := binary.BigEndian.Uint32(b.keyTable[off+12 : off+16])
			if id == 0 {
				copy(b.keyTable[off:off+12], token[:12])
				binary.BigEndian.PutUint32(b.keyTable[off+12:off+16], keyID+1)
				return nil
			}
			if bytes.Equal(b.keyTable[off:off+12], token[:]) {
				return errors.New("snapshots: V6 logical-key fingerprint collision")
			}
			slot = (slot + 1) & b.keyMask
		}
		return errors.New("snapshots: V6 logical-key table is full")
	})
	if err != nil {
		return err
	}
	copy(b.dictionaryDigest[:], digest.Sum(nil))
	return nil
}

func (b *stateDomainChangeV6Build) ResetPostings() error {
	if b == nil {
		return errors.New("snapshots: nil V6 posting reset")
	}
	if b.postings != nil {
		_ = b.postings.Close()
	}
	postings, err := etl.NewCollector(b.opts)
	if err != nil {
		return fmt.Errorf("snapshots: recreate V6 posting ETL: %w", err)
	}
	b.postings = postings
	b.offsets.Close()
	b.offsets = nil
	return nil
}

func (b *stateDomainChangeV6Build) dictionaryBlock(index int) ([][]byte, error) {
	if keys, ok := b.cache[index]; ok {
		return keys, nil
	}
	if index < 0 || index >= len(b.blocks) {
		return nil, errors.New("snapshots: V6 dictionary block outside range")
	}
	block := b.blocks[index]
	raw := make([]byte, block.length)
	if _, err := b.dictionary.ReadAt(raw, int64(block.offset)); err != nil {
		return nil, err
	}
	keys, err := decodeStateDomainChangeV6DictionaryBlock(raw, block.count)
	if err != nil {
		return nil, err
	}
	if !bytes.Equal(keys[0], block.firstKey) {
		return nil, errors.New("snapshots: V6 dictionary first key mismatch")
	}
	if len(b.cacheOrder) >= stateDomainChangeV6DictionaryCacheBlocks {
		delete(b.cache, b.cacheOrder[0])
		b.cacheOrder = b.cacheOrder[1:]
	}
	b.cache[index] = keys
	b.cacheOrder = append(b.cacheOrder, index)
	return keys, nil
}

func (b *stateDomainChangeV6Build) KeyID(key []byte) (uint32, error) {
	if b == nil {
		return 0, errors.New("snapshots: nil V6 dictionary")
	}
	if len(b.keyTable) != 0 {
		token := stateDomainChangeV6BuildKeyToken(b.keyHashSeed, key)
		slot := binary.LittleEndian.Uint64(token[:8]) & b.keyMask
		for probes := uint64(0); probes <= b.keyMask; probes++ {
			off := slot * 16
			id := binary.BigEndian.Uint32(b.keyTable[off+12 : off+16])
			if id == 0 {
				break
			}
			if bytes.Equal(b.keyTable[off:off+12], token[:]) {
				return id - 1, nil
			}
			slot = (slot + 1) & b.keyMask
		}
		return 0, fmt.Errorf("snapshots: V6 key %x not found in fingerprint table", key)
	}
	if len(b.blocks) == 0 {
		return 0, errors.New("snapshots: empty V6 dictionary")
	}
	blockIndex := sort.Search(len(b.blocks), func(i int) bool { return bytes.Compare(b.blocks[i].firstKey, key) > 0 }) - 1
	if blockIndex < 0 {
		return 0, errors.New("snapshots: V6 key not found")
	}
	keys, err := b.dictionaryBlock(blockIndex)
	if err != nil {
		return 0, err
	}
	within := sort.Search(len(keys), func(i int) bool { return bytes.Compare(keys[i], key) >= 0 })
	if within == len(keys) || !bytes.Equal(keys[within], key) {
		return 0, fmt.Errorf("snapshots: V6 key %x not found", key)
	}
	return uint32(blockIndex*stateDomainChangeBinaryAccessorV6BlockKeys + within), nil
}

func (b *stateDomainChangeV6Build) CollectPosting(keyID uint32, txNum, offset, recordIndex uint64) error {
	if b == nil || b.postings == nil || recordIndex > math.MaxUint32 || offset > stateDomainChangeBinaryAccessorV5MaxOffset {
		return errors.New("snapshots: invalid V6 posting")
	}
	if b.offsets == nil {
		var err error
		b.offsets, err = newHistoryAccessorOffsetBuilder(filepath.Dir(b.dictName), filepath.Base(b.dictName))
		if err != nil {
			return err
		}
	}
	if err := b.offsets.Add(recordIndex, offset); err != nil {
		return err
	}
	return b.postings.PutEncoded(8, stateDomainChangeBinaryAccessorV6PostingSize, func(key, value []byte) {
		binary.BigEndian.PutUint32(key[:4], keyID)
		binary.BigEndian.PutUint32(key[4:], uint32(recordIndex))
		binary.BigEndian.PutUint64(value[:8], txNum)
		_ = putStateDomainChangeBinaryAccessorV5Offset(value[8:14], offset)
		binary.BigEndian.PutUint32(value[14:18], uint32(recordIndex))
	})
}

// stateDomainChangeV6BuildKeyToken is an ephemeral build-time fingerprint.
// The table never reaches the published file, so a per-process randomized hash
// avoids the much more expensive cryptographic SHA-256 on every history row.
// The independent CRC supplies the same 96-bit collision guard used by the old
// table; an actual collision still fails the build instead of misassigning an
// accessor key ID.
func stateDomainChangeV6BuildKeyToken(seed maphash.Seed, key []byte) (token [12]byte) {
	binary.LittleEndian.PutUint64(token[:8], maphash.Bytes(seed, key))
	binary.BigEndian.PutUint32(token[8:], crc32.ChecksumIEEE(key))
	return token
}

type stateDomainChangeV6PostingWriter struct {
	postings *bufio.Writer
	meta     *bufio.Writer
	expected uint32
	keyID    uint32
	haveKey  bool
	offset   uint64
	count    uint32
	rows     uint64
}

// stateDomainChangeV7PostingWriter consumes the same bounded ETL rows as V6,
// but publishes one delta-framed stream per logical key. A single key is the
// only buffered unit; the global posting set remains an external sort.
type stateDomainChangeV7PostingWriter struct {
	ctx              context.Context
	postings         *bufio.Writer
	meta             *bufio.Writer
	scratch          *historyPostingScratch
	expected         uint32
	fromTx           uint64
	keyID            uint32
	haveKey          bool
	offset           uint64
	rows             uint64
	current          []stateDomainChangeBinaryAccessorV6Posting
	frames           []stateDomainChangeBinaryAccessorV7Frame
	last             stateDomainChangeBinaryAccessorV6Posting
	haveLast         bool
	inlineSingletons bool
	version          uint32
}

func (w *stateDomainChangeV7PostingWriter) Put(key, value []byte) error {
	if len(key) != 8 || len(value) != stateDomainChangeBinaryAccessorV6PostingSize {
		return errors.New("snapshots: invalid V7 posting ETL row")
	}
	keyID := binary.BigEndian.Uint32(key[:4])
	if keyID >= w.expected {
		return errors.New("snapshots: V7 posting key ID outside dictionary")
	}
	if !w.haveKey {
		if keyID != 0 {
			return errors.New("snapshots: V7 postings do not start at key zero")
		}
		w.keyID, w.haveKey = keyID, true
	} else if keyID != w.keyID {
		if keyID != w.keyID+1 {
			return errors.New("snapshots: V7 posting key ID gap")
		}
		if err := w.flushKey(); err != nil {
			return err
		}
		w.keyID = keyID
	}
	posting, err := decodeStateDomainChangeBinaryAccessorV6Posting(value)
	if err != nil {
		return err
	}
	if w.haveLast {
		if posting.txNum < w.last.txNum || posting.offset <= w.last.offset || posting.recordIndex <= w.last.recordIndex {
			return errors.New("snapshots: V7 postings are not ordered")
		}
	}
	w.current = append(w.current, posting)
	w.last, w.haveLast = posting, true
	w.rows++
	if len(w.current) == int(stateDomainChangeBinaryAccessorV7FramePostings) {
		return w.flushFrame()
	}
	return nil
}

func (*stateDomainChangeV7PostingWriter) Delete([]byte) error {
	return errors.New("snapshots: V7 posting delete")
}

func (w *stateDomainChangeV7PostingWriter) flushKey() error {
	if w.inlineSingletons && len(w.frames) == 0 && len(w.current) == 1 {
		if err := w.writeMeta(w.offset, 1, w.current[0]); err != nil {
			return err
		}
		w.current = w.current[:0]
		w.haveLast = false
		historyPostingMemoryKeys.Inc(1)
		return w.scratch.Reset()
	}

	if len(w.current) != 0 {
		if err := w.flushFrame(); err != nil {
			return err
		}
	}
	if len(w.frames) == 0 {
		return errors.New("snapshots: V7 key has no postings")
	}
	written, count, err := writeStateDomainChangeBinaryAccessorV7PostingFrames(contextWriter{ctx: w.ctx, w: w.postings}, w.scratch, w.frames)
	if err != nil {
		return err
	}
	if err := w.writeMeta(w.offset, count, stateDomainChangeBinaryAccessorV6Posting{}); err != nil {
		return err
	}

	w.offset += written
	w.current = w.current[:0]
	w.frames = w.frames[:0]
	w.haveLast = false
	if w.scratch.spilled {
		historyPostingSpillKeys.Inc(1)
		historyPostingSpillBytes.Inc(int64(w.scratch.size))
	} else {
		historyPostingMemoryKeys.Inc(1)
	}
	return w.scratch.Reset()
}

func (w *stateDomainChangeV7PostingWriter) writeMeta(off uint64, count uint32, p stateDomainChangeBinaryAccessorV6Posting) error {
	var raw [32]byte
	binary.BigEndian.PutUint64(raw[:8], off)
	binary.BigEndian.PutUint32(raw[8:12], count)
	size := 12
	if w.inlineSingletons {
		size = 32
		binary.BigEndian.PutUint64(raw[12:20], p.txNum)
		binary.BigEndian.PutUint64(raw[20:28], p.offset)
		binary.BigEndian.PutUint32(raw[28:32], p.recordIndex)
	}
	_, err := w.meta.Write(raw[:size])
	return err
}

func (w *stateDomainChangeV7PostingWriter) flushFrame() error {
	if len(w.current) == 0 || w.scratch == nil {
		return errors.New("snapshots: invalid V7 posting frame")
	}
	encoded, err := encodeStateDomainChangeBinaryAccessorPostingListVersion(w.fromTx, w.current, w.version)
	if err != nil {
		return err
	}
	if len(encoded) < 5 || encoded[0] != stateDomainChangeBinaryAccessorV7Single {
		return errors.New("snapshots: invalid bounded V7 posting frame encoding")
	}
	frameData := encoded[1 : len(encoded)-4]
	off := w.scratch.size
	if err := w.scratch.Write(frameData); err != nil {
		return err
	}
	w.frames = append(w.frames, stateDomainChangeBinaryAccessorV7Frame{
		firstTx: w.current[0].txNum, dataOff: uint32(off), dataLen: uint32(len(frameData)),
		count: uint16(len(w.current)), crc: binary.BigEndian.Uint32(encoded[len(encoded)-4:]),
	})
	w.current = w.current[:0]
	return nil
}

func (w *stateDomainChangeV7PostingWriter) Finish() error {
	if w.expected == 0 {
		if w.haveKey {
			return errors.New("snapshots: V7 empty dictionary has postings")
		}
		return nil
	}
	if !w.haveKey || w.keyID+1 != w.expected {
		return errors.New("snapshots: V7 postings do not cover dictionary")
	}
	if err := w.flushKey(); err != nil {
		return err
	}
	if err := w.postings.Flush(); err != nil {
		return err
	}
	return w.meta.Flush()
}

func (w *stateDomainChangeV6PostingWriter) Put(key, value []byte) error {
	if len(key) != 8 || len(value) != stateDomainChangeBinaryAccessorV6PostingSize {
		return errors.New("snapshots: invalid V6 posting ETL row")
	}
	keyID := binary.BigEndian.Uint32(key[:4])
	if keyID >= w.expected {
		return errors.New("snapshots: V6 posting key ID outside dictionary")
	}
	if !w.haveKey {
		if keyID != 0 {
			return errors.New("snapshots: V6 postings do not start at key zero")
		}
		w.keyID, w.haveKey = keyID, true
	} else if keyID != w.keyID {
		if keyID != w.keyID+1 {
			return errors.New("snapshots: V6 posting key ID gap")
		}
		if err := w.flushMeta(); err != nil {
			return err
		}
		w.keyID = keyID
	}
	if _, err := w.postings.Write(value); err != nil {
		return err
	}
	w.count++
	w.rows++
	return nil
}
func (*stateDomainChangeV6PostingWriter) Delete([]byte) error {
	return errors.New("snapshots: V6 posting delete")
}
func (w *stateDomainChangeV6PostingWriter) flushMeta() error {
	var raw [12]byte
	binary.BigEndian.PutUint64(raw[:8], w.offset)
	binary.BigEndian.PutUint32(raw[8:12], w.count)
	if _, err := w.meta.Write(raw[:]); err != nil {
		return err
	}
	w.offset += uint64(w.count) * stateDomainChangeBinaryAccessorV6PostingSize
	w.count = 0
	return nil
}
func (w *stateDomainChangeV6PostingWriter) Finish() error {
	if w.expected == 0 {
		if w.haveKey {
			return errors.New("snapshots: V6 empty dictionary has postings")
		}
		return nil
	}
	if !w.haveKey || w.keyID+1 != w.expected {
		return errors.New("snapshots: V6 postings do not cover dictionary")
	}
	if err := w.flushMeta(); err != nil {
		return err
	}
	if err := w.postings.Flush(); err != nil {
		return err
	}
	return w.meta.Flush()
}

func (b *stateDomainChangeV6Build) BuildAccessor(dir string, ref SegmentRef, recordCount uint64) (SegmentRef, etl.Stats, error) {
	return b.BuildAccessorContext(context.Background(), dir, ref, recordCount)
}

func (b *stateDomainChangeV6Build) BuildAccessorContext(ctx context.Context, dir string, ref SegmentRef, recordCount uint64) (SegmentRef, etl.Stats, error) {
	return b.buildAccessorContextVersion(ctx, dir, ref, recordCount, stateDomainChangeBinaryAccessorVersionV10)
}

func (b *stateDomainChangeV6Build) buildAccessorContextVersion(ctx context.Context, dir string, ref SegmentRef, recordCount uint64, version uint32) (SegmentRef, etl.Stats, error) {
	if !isStateDomainChangeFramedAccessor(version) {
		return SegmentRef{}, etl.Stats{}, errors.New("snapshots: unsupported accessor build version")
	}
	metaSize := 12
	if isHistoryInlineAccessor(version) {
		metaSize = 32
	}

	if err := contextError(ctx); err != nil {
		return SegmentRef{}, etl.Stats{}, err
	}
	if b == nil || b.postings == nil || uint64(b.keyCount) > recordCount {
		return SegmentRef{}, etl.Stats{}, errors.New("snapshots: invalid V6 accessor build")
	}
	var owners *historyOwnerTable
	if version == stateDomainChangeBinaryAccessorVersionV10 {
		var err error
		owners, err = b.buildHistoryOwnerTable(ctx)
		if err != nil {
			return SegmentRef{}, etl.Stats{}, err
		}
		if owners == nil {
			version = stateDomainChangeBinaryAccessorVersionV9
		}
	}
	abs := filepath.Join(dir, ref.Path)
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return SegmentRef{}, etl.Stats{}, err
	}
	postingFile, postingName, err := createStateDomainChangeBinaryTempFileInDir(filepath.Dir(abs), filepath.Base(abs)+".postings")
	if err != nil {
		return SegmentRef{}, etl.Stats{}, err
	}
	defer func() { _ = postingFile.Close(); _ = os.Remove(postingName) }()
	metaFile, metaName, err := createStateDomainChangeBinaryTempFileInDir(filepath.Dir(abs), filepath.Base(abs)+".meta")
	if err != nil {
		return SegmentRef{}, etl.Stats{}, err
	}
	defer func() { _ = metaFile.Close(); _ = os.Remove(metaName) }()
	scratch := &historyPostingScratch{ctx: ctx, dir: filepath.Dir(abs), base: filepath.Base(abs) + ".posting-frames"}
	defer scratch.Close()
	writer := &stateDomainChangeV7PostingWriter{ctx: ctx, postings: bufio.NewWriterSize(postingFile, 1<<20), meta: bufio.NewWriterSize(metaFile, 1<<20), scratch: scratch, expected: b.keyCount, fromTx: ref.FromTxNum, version: version, inlineSingletons: isHistoryInlineAccessor(version)}
	postingStats, err := loadHistoryETLContext(ctx, b.postings, writer)
	if err != nil {
		return SegmentRef{}, postingStats, err
	}
	if err := writer.Finish(); err != nil {
		return SegmentRef{}, postingStats, err
	}
	if writer.rows != recordCount {
		return SegmentRef{}, postingStats, fmt.Errorf("snapshots: V6 postings wrote %d records, want %d", writer.rows, recordCount)
	}
	_ = b.postings.Close()
	b.postings = nil
	keyData, keyDataName, err := createStateDomainChangeBinaryTempFileInDir(filepath.Dir(abs), filepath.Base(abs)+".keys")
	if err != nil {
		return SegmentRef{}, postingStats, err
	}
	defer func(f *os.File, n string) { _ = f.Close(); _ = os.Remove(n) }(keyData, keyDataName)
	var plainData *os.File
	var plainWriter *bufio.Writer
	var plainOffset uint64
	var plainLargest int
	var plainBlocks []stateDomainChangeBinaryAccessorV6Block
	if owners != nil {
		f, n, err := createStateDomainChangeBinaryTempFileInDir(filepath.Dir(abs), filepath.Base(abs)+".plain-keys")
		if err != nil {
			return SegmentRef{}, postingStats, err
		}
		plainData = f
		defer func() { _ = f.Close(); _ = os.Remove(n) }()
		plainWriter = bufio.NewWriterSize(f, 1<<20)
	}
	metaReader := bufio.NewReaderSize(io.NewSectionReader(metaFile, 0, int64(b.keyCount)*int64(metaSize)), 64<<10)
	keyWriter := bufio.NewWriterSize(keyData, 1<<20)
	var keyOffset uint64
	var largestRawKeyBlock int
	var blocks []stateDomainChangeBinaryAccessorV6Block
	for blockIndex := range b.blocks {
		if err := contextError(ctx); err != nil {
			return SegmentRef{}, postingStats, err
		}
		keys, err := b.dictionaryBlock(blockIndex)
		if err != nil {
			return SegmentRef{}, postingStats, err
		}
		records := make([]stateDomainChangeBinaryAccessorV6Key, len(keys))
		for i, key := range keys {
			keyID := uint32(blockIndex*stateDomainChangeBinaryAccessorV6BlockKeys + i)
			var raw [32]byte
			if _, err := io.ReadFull(metaReader, raw[:metaSize]); err != nil {
				return SegmentRef{}, postingStats, err
			}
			records[i] = stateDomainChangeBinaryAccessorV6Key{key: key, keyID: keyID, postingOff: binary.BigEndian.Uint64(raw[:8]), postingCount: binary.BigEndian.Uint32(raw[8:12]), inlinePosting: stateDomainChangeBinaryAccessorV6Posting{txNum: binary.BigEndian.Uint64(raw[12:20]), offset: binary.BigEndian.Uint64(raw[20:28]), recordIndex: binary.BigEndian.Uint32(raw[28:32])}}
		}
		var raw, stored []byte
		var storedLen uint32
		if owners != nil {
			raw, stored, storedLen, err = encodeHistoryOwnerKeyBlock(records, ref.FromTxNum, owners, &largestRawKeyBlock)
			if err != nil {
				return SegmentRef{}, postingStats, err
			}
			plain, err := encodeStateDomainChangeBinaryAccessorV8KeyBlock(records, ref.FromTxNum)
			if err != nil {
				return SegmentRef{}, postingStats, err
			}
			packed, flags, err := compressHistoryDictionaryKeyBlock(plain, &plainLargest)
			if err != nil {
				return SegmentRef{}, postingStats, err
			}
			if _, err = plainWriter.Write(packed); err != nil {
				return SegmentRef{}, postingStats, err
			}
			plainBlocks = append(plainBlocks, stateDomainChangeBinaryAccessorV6Block{firstKey: append([]byte(nil), keys[0]...), dataOff: plainOffset, dataLen: flags, rawLen: uint32(len(plain)), checksum: crc32.ChecksumIEEE(plain), keyCount: uint32(len(keys))})
			plainOffset += uint64(len(packed))
		} else {
			if isHistoryInlineAccessor(version) {
				raw, err = encodeStateDomainChangeBinaryAccessorV8KeyBlock(records, ref.FromTxNum)
			} else {
				raw, err = encodeStateDomainChangeBinaryAccessorV6KeyBlock(records)
			}
			if err != nil {
				return SegmentRef{}, postingStats, err
			}
			stored, storedLen, err = compressHistoryDictionaryKeyBlock(raw, &largestRawKeyBlock)
			if err != nil {
				return SegmentRef{}, postingStats, err
			}
		}
		off := keyOffset
		if _, err := keyWriter.Write(stored); err != nil {
			return SegmentRef{}, postingStats, err
		}
		keyOffset += uint64(len(stored))
		blocks = append(blocks, stateDomainChangeBinaryAccessorV6Block{firstKey: append([]byte(nil), keys[0]...), dataOff: off, dataLen: storedLen, rawLen: uint32(len(raw)), checksum: crc32.ChecksumIEEE(raw), keyCount: uint32(len(keys))})
	}
	if err := keyWriter.Flush(); err != nil {
		return SegmentRef{}, postingStats, err
	}
	keyStat, err := keyData.Stat()
	if err != nil {
		return SegmentRef{}, postingStats, err
	}
	if owners != nil {
		if err := plainWriter.Flush(); err != nil {
			return SegmentRef{}, postingStats, err
		}
		plainStat, err := plainData.Stat()
		if err != nil {
			return SegmentRef{}, postingStats, err
		}
		if uint64(keyStat.Size())+owners.size() >= uint64(plainStat.Size()) {
			version = stateDomainChangeBinaryAccessorVersionV9
			owners = nil
			keyData, keyStat, blocks = plainData, plainStat, plainBlocks
		}
	}
	postingStat, err := postingFile.Stat()
	if err != nil {
		return SegmentRef{}, postingStats, err
	}
	dirLen := uint64(0)
	for _, block := range blocks {
		dirLen += 2 + uint64(len(block.firstKey)) + stateDomainChangeBinaryAccessorV6BlockTail
	}
	dirLen += uint64(len(blocks)) * 8
	var sparse []byte
	if isHistoryInlineAccessor(version) {
		sparse = encodeHistoryAccessorSparseDirectory(blocks)
	}
	dirLen += uint64(len(sparse))
	tmp, tmpName, err := createStateDomainChangeBinaryTempFileInDir(filepath.Dir(abs), filepath.Base(abs))
	if err != nil {
		return SegmentRef{}, postingStats, err
	}
	defer func() { _ = tmp.Close(); _ = os.Remove(tmpName) }()
	output := bufio.NewWriterSize(contextWriter{ctx: ctx, w: tmp}, 1<<20)
	metadata := newSnapshotMetadataWriter(output)
	var header [stateDomainChangeBinaryAccessorV7HeaderSize]byte
	copy(header[:8], stateDomainChangeBinaryAccessorMagic[:])
	binary.BigEndian.PutUint32(header[8:12], version)
	binary.BigEndian.PutUint64(header[12:20], ref.FromTxNum)
	binary.BigEndian.PutUint64(header[20:28], ref.ToTxNum)
	binary.BigEndian.PutUint64(header[28:36], recordCount)
	binary.BigEndian.PutUint32(header[36:40], stateDomainChangeBinaryAccessorV6BlockKeys)
	binary.BigEndian.PutUint64(header[40:48], uint64(b.keyCount))
	binary.BigEndian.PutUint64(header[48:56], uint64(len(blocks)))
	binary.BigEndian.PutUint64(header[56:64], dirLen)
	binary.BigEndian.PutUint64(header[64:72], uint64(keyStat.Size()))
	copy(header[72:104], b.dictionaryDigest[:])
	binary.BigEndian.PutUint64(header[104:112], uint64(postingStat.Size()))
	binary.BigEndian.PutUint32(header[116:120], uint32(len(sparse)))
	binary.BigEndian.PutUint32(header[112:116], stateDomainChangeAccessorHeaderCRC(header[:], version))
	if _, err := metadata.Write(header[:]); err != nil {
		return SegmentRef{}, postingStats, err
	}
	keyDataBase := stateDomainChangeBinaryAccessorV7HeaderSize + dirLen
	entryOffset := stateDomainChangeBinaryAccessorV7HeaderSize + uint64(len(blocks))*8
	var offsetRaw [8]byte
	for _, block := range blocks {
		binary.BigEndian.PutUint64(offsetRaw[:], entryOffset)
		if _, err := metadata.Write(offsetRaw[:]); err != nil {
			return SegmentRef{}, postingStats, err
		}
		entryOffset += 2 + uint64(len(block.firstKey)) + stateDomainChangeBinaryAccessorV6BlockTail
	}
	var tail [stateDomainChangeBinaryAccessorV6BlockTail]byte
	for _, block := range blocks {
		if len(block.firstKey) > math.MaxUint16 {
			return SegmentRef{}, postingStats, errors.New("snapshots: V6 key too long")
		}
		var l [2]byte
		binary.BigEndian.PutUint16(l[:], uint16(len(block.firstKey)))
		if _, err := metadata.Write(l[:]); err != nil {
			return SegmentRef{}, postingStats, err
		}
		if _, err := metadata.Write(block.firstKey); err != nil {
			return SegmentRef{}, postingStats, err
		}
		binary.BigEndian.PutUint64(tail[0:8], keyDataBase+block.dataOff)
		binary.BigEndian.PutUint32(tail[8:12], block.dataLen)
		binary.BigEndian.PutUint32(tail[12:16], block.rawLen)
		binary.BigEndian.PutUint32(tail[16:20], block.checksum)
		binary.BigEndian.PutUint32(tail[20:24], block.keyCount)
		c := crc32.NewIEEE()
		c.Write(block.firstKey)
		c.Write(tail[:24])
		binary.BigEndian.PutUint32(tail[24:28], c.Sum32())
		if _, err := metadata.Write(tail[:]); err != nil {
			return SegmentRef{}, postingStats, err
		}
	}
	if _, err := metadata.Write(sparse); err != nil {
		return SegmentRef{}, postingStats, err
	}
	for _, src := range []*os.File{keyData, postingFile} {
		if _, err := src.Seek(0, io.SeekStart); err != nil {
			return SegmentRef{}, postingStats, err
		}
		if _, err := copyStateDomainChangeHistoryData(metadata, contextReader{ctx: ctx, r: src}); err != nil {
			return SegmentRef{}, postingStats, err
		}
	}
	if isHistoryOffsetAccessor(version) {
		if b.offsets == nil {
			b.offsets, err = newHistoryAccessorOffsetBuilder(filepath.Dir(abs), filepath.Base(abs))
			if err != nil {
				return SegmentRef{}, postingStats, err
			}
		}
		if err := b.offsets.AppendTo(metadata, recordCount); err != nil {
			return SegmentRef{}, postingStats, err
		}
	}
	if owners != nil {
		if err := owners.appendTo(metadata, metadata.size); err != nil {
			return SegmentRef{}, postingStats, err
		}
	}
	if uint64(postingStat.Size()) != writer.offset {
		return SegmentRef{}, postingStats, errors.New("snapshots: V7 posting file size mismatch")
	}
	if err := contextError(ctx); err != nil {
		return SegmentRef{}, postingStats, err
	}
	if err := output.Flush(); err != nil {
		return SegmentRef{}, postingStats, err
	}
	result, err := finalizeStateDomainChangeHistoryFileWithMetadata(dir, ref, tmp, tmpName, metadata.Metadata(), false)
	return result, postingStats, err
}

// Preserve the cancellation cause for lifecycle shutdown handling instead of
// reporting a cooperative ETL stop as a compaction failure.
func loadHistoryETLContext(ctx context.Context, collector *etl.Collector, writer ethdb.KeyValueWriter) (etl.Stats, error) {
	stats, err := collector.LoadInterruptible(writer, func() bool { return contextError(ctx) != nil })
	if errors.Is(err, etl.ErrLoadInterrupted) {
		if ctxErr := contextError(ctx); ctxErr != nil {
			err = ctxErr
		}
	}
	return stats, err
}

var _ ethdb.KeyValueWriter = (*stateDomainChangeV6DictionaryWriter)(nil)
var _ ethdb.KeyValueWriter = (*stateDomainChangeV6PostingWriter)(nil)

// Keeping each new largest block raw ensures aggregate physical keyDataLen is
// at least every rawLen, as required by the existing bounded reader. Equal-size
// later blocks may compress; no dictionary-wide second pass is needed.
func compressHistoryDictionaryKeyBlock(raw []byte, largestRaw *int) ([]byte, uint32, error) {
	rawLength := uint32(len(raw)) | stateDomainChangeBinaryAccessorV6StoredRaw
	if len(raw) > *largestRaw {
		*largestRaw = len(raw)
		return raw, rawLength, nil
	}
	enc, _, err := cbCodec()
	if err != nil {
		return nil, 0, err
	}
	compressed := enc.EncodeAll(raw, nil)
	if len(compressed)*10 > len(raw)*9 {
		return raw, rawLength, nil
	}
	return compressed, uint32(len(compressed)), nil
}

package snapshots

import (
	"bytes"
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"math"
	"sort"
	"sync"

	"github.com/tronprotocol/go-tron/core/rawdb"
)

const (
	stateDomainChangeBinaryAccessorV7HeaderSize    = uint64(120)
	stateDomainChangeBinaryAccessorV7FramePostings = uint32(128)
	stateDomainChangeBinaryAccessorV7FrameDirSize  = uint64(24)
	stateDomainChangeBinaryAccessorV7Single        = byte(0)
	stateDomainChangeBinaryAccessorV7Framed        = byte(1)
	stateDomainChangeBinaryAccessorV7SingleReadMax = int(stateDomainChangeBinaryAccessorV7FramePostings)*3*binary.MaxVarintLen64 + 4
)

type stateDomainChangeBinaryAccessorV7SingleReadBuffer [stateDomainChangeBinaryAccessorV7SingleReadMax]byte

var stateDomainChangeBinaryAccessorV7SingleReadBufferPool = sync.Pool{
	New: func() any { return new(stateDomainChangeBinaryAccessorV7SingleReadBuffer) },
}

type stateDomainChangeBinaryAccessorV7Frame struct {
	firstTx uint64
	dataOff uint32
	dataLen uint32
	count   uint16
	crc     uint32
}

type stateDomainChangeBinaryAccessorV7PostingDirectory struct {
	base       uint64
	frameCount uint64
	prefixLen  uint64
	dataStart  uint64
	single     bool
}

func decodeStateDomainChangeBinaryAccessorV7Header(r io.ReaderAt, fileSize uint64) (stateDomainChangeBinaryAccessorV6Header, error) {
	if fileSize > math.MaxInt64 {
		return stateDomainChangeBinaryAccessorV6Header{}, errors.New("snapshots: accessor size exceeds int64")
	}
	if fileSize < stateDomainChangeBinaryAccessorV7HeaderSize {
		return stateDomainChangeBinaryAccessorV6Header{}, io.ErrUnexpectedEOF
	}
	var raw [stateDomainChangeBinaryAccessorV7HeaderSize]byte
	if _, err := r.ReadAt(raw[:], 0); err != nil {
		return stateDomainChangeBinaryAccessorV6Header{}, err
	}
	if !bytes.Equal(raw[:8], stateDomainChangeBinaryAccessorMagic[:]) || !isStateDomainChangeFramedAccessor(binary.BigEndian.Uint32(raw[8:12])) {
		return stateDomainChangeBinaryAccessorV6Header{}, errors.New("snapshots: invalid state-domain-change V7 accessor magic/version")
	}
	if binary.BigEndian.Uint32(raw[36:40]) != stateDomainChangeBinaryAccessorV6BlockKeys || binary.BigEndian.Uint32(raw[112:116]) != stateDomainChangeAccessorHeaderCRC(raw[:], binary.BigEndian.Uint32(raw[8:12])) || binary.BigEndian.Uint32(raw[8:12]) == stateDomainChangeBinaryVersionV7 && !bytes.Equal(raw[116:120], []byte{0, 0, 0, 0}) {
		return stateDomainChangeBinaryAccessorV6Header{}, errors.New("snapshots: invalid state-domain-change V7 accessor header")
	}
	h := stateDomainChangeBinaryAccessorV6Header{
		version: binary.BigEndian.Uint32(raw[8:12]), headerSize: stateDomainChangeBinaryAccessorV7HeaderSize,
		fromTxNum: binary.BigEndian.Uint64(raw[12:20]), toTxNum: binary.BigEndian.Uint64(raw[20:28]),
		recordCount: binary.BigEndian.Uint64(raw[28:36]), keyCount: binary.BigEndian.Uint64(raw[40:48]),
		blockCount: binary.BigEndian.Uint64(raw[48:56]), blockDirLen: binary.BigEndian.Uint64(raw[56:64]),
		keyDataLen: binary.BigEndian.Uint64(raw[64:72]), postingLen: binary.BigEndian.Uint64(raw[104:112]),
	}
	copy(h.dictionaryDigest[:], raw[72:104])
	if isHistoryInlineAccessor(h.version) {
		h.sparseLen = uint64(binary.BigEndian.Uint32(raw[116:120]))
		if h.fromTxNum > h.toTxNum || h.sparseLen > historyAccessorDirectoryReadLimit || h.sparseLen > h.blockDirLen || h.sparseLen != 0 && (h.sparseLen < 8 || h.blockCount <= historyAccessorSparseStride) {
			return h, errors.New("snapshots: invalid V8 sparse directory header")
		}
	}
	if h.recordCount > math.MaxUint32 || h.keyCount > math.MaxUint32 || h.blockCount != ceilDiv(h.keyCount, stateDomainChangeBinaryAccessorV6BlockKeys) || h.blockCount > math.MaxUint64/8 || h.blockDirLen-h.sparseLen < h.blockCount*8 {
		return h, errors.New("snapshots: invalid state-domain-change V7 accessor counts")
	}
	total, overflow := checkedAdd(h.headerSize, h.blockDirLen)
	if !overflow {
		total, overflow = checkedAdd(total, h.keyDataLen)
	}
	if !overflow {
		total, overflow = checkedAdd(total, h.postingLen)
	}
	if !overflow && isHistoryOffsetAccessor(h.version) {
		prefixSize := fileSize
		if h.version == stateDomainChangeBinaryAccessorVersionV10 {
			var err error
			h.owners, err = decodeHistoryOwnerFooter(r, fileSize)
			if err != nil {
				return h, err
			}
			if h.owners.count > h.keyCount {
				return h, errors.New("snapshots: owner count exceeds key count")
			}
			prefixSize = h.owners.prefixSize
		}
		if err := decodeHistoryOffsetFooter(r, prefixSize, total, &h); err != nil {
			return h, err
		}
		total = fileSize
	}
	if overflow || total != fileSize {
		return h, errors.New("snapshots: invalid state-domain-change V7 accessor length")
	}
	return h, nil
}

func decodeStateDomainChangeBinaryAccessorKeyHeader(r io.ReaderAt, fileSize uint64) (stateDomainChangeBinaryAccessorV6Header, error) {
	var raw [12]byte
	if _, err := r.ReadAt(raw[:], 0); err != nil {
		return stateDomainChangeBinaryAccessorV6Header{}, err
	}
	switch binary.BigEndian.Uint32(raw[8:12]) {
	case stateDomainChangeBinaryVersionV6:
		return decodeStateDomainChangeBinaryAccessorV6Header(r, fileSize)
	case stateDomainChangeBinaryVersionV7, stateDomainChangeBinaryAccessorVersionV8, stateDomainChangeBinaryAccessorVersionV9, stateDomainChangeBinaryAccessorVersionV10:
		return decodeStateDomainChangeBinaryAccessorV7Header(r, fileSize)
	default:
		return stateDomainChangeBinaryAccessorV6Header{}, errors.New("snapshots: unsupported key-oriented accessor version")
	}
}

func stateDomainChangeBinaryAccessorV7Lookup(r io.ReaderAt, fileSize uint64, lookup []byte) (stateDomainChangeBinaryAccessorV6Header, stateDomainChangeBinaryAccessorV6Record, bool, error) {
	h, err := decodeStateDomainChangeBinaryAccessorV7Header(r, fileSize)
	if err != nil {
		return h, stateDomainChangeBinaryAccessorV6Record{}, false, err
	}
	block, blockIndex, ok, err := findHistoryAccessorKeyBlock(r, h, lookup)
	if err != nil || !ok {
		return h, stateDomainChangeBinaryAccessorV6Record{}, false, err
	}

	records, err := stateDomainChangeBinaryAccessorV6ReadBlock(r, fileSize, h, block, uint32(blockIndex*stateDomainChangeBinaryAccessorV6BlockKeys))
	if err != nil {
		return h, stateDomainChangeBinaryAccessorV6Record{}, false, err
	}
