func iterateStateDomainChangeBinarySegmentByAccessorV7Record(segment io.ReaderAt, segmentSize uint64, accessor io.ReaderAt, h stateDomainChangeBinaryAccessorV6Header, record stateDomainChangeBinaryAccessorV6Record, fromTxNum, toTxNum uint64, fn func(*rawdb.StateDomainChange) (bool, error), shared ...*historyAccessorOffsetResolver) error {
	var resolver *historyAccessorOffsetResolver
	if isHistoryOffsetAccessor(h.version) {
		if len(shared) > 0 {
			resolver = shared[0]
		}
		if resolver == nil {
			resolver = newHistoryAccessorOffsetResolver(accessor, h)
		}
	}
	directory, err := stateDomainChangeBinaryAccessorV7OpenPostingDirectory(accessor, h, record)
	if err != nil {
		return err
	}
	low, high := uint64(0), directory.frameCount
	for low < high {
		mid := low + (high-low)/2
		frame, err := stateDomainChangeBinaryAccessorV7ReadPostingDirectoryFrame(accessor, h, record, directory, mid)
		if err != nil {
			return err
		}
		if frame.firstTx < fromTxNum {
			low = mid + 1
		} else {
			high = mid
		}
	}
	start := low
	if start > 0 {
		start--
	}
	var previous stateDomainChangeBinaryAccessorV7Frame
	havePrevious := false
	for i := start; i < directory.frameCount; i++ {
		frame, err := stateDomainChangeBinaryAccessorV7ReadPostingDirectoryFrame(accessor, h, record, directory, i)
		if err != nil {
			return err
		}
		if havePrevious && (frame.firstTx < previous.firstTx || uint64(frame.dataOff) != uint64(previous.dataOff)+uint64(previous.dataLen)) {
			return errors.New("snapshots: invalid V7 accessor posting frame sequence")
		}
		if i > start && frame.firstTx > toTxNum {
			return nil
		}
		postings, _, err := readHistoryAccessorRawFrame(accessor, h, record, frame)
		if err != nil {
			return err
		}
		for _, posting := range postings {
			if posting.txNum < fromTxNum {
				continue
			}
			if posting.txNum > toTxNum {
				return nil
			}
			if resolver != nil && !record.inline {
				posting.offset, err = resolver.Offset(posting.recordIndex)
				if err != nil {
					return err
				}
			}
			change, _, err := readStateDomainChangeBinaryRecordAtBoundedIndex(segment, posting.offset, segmentSize, uint64(posting.recordIndex))
			if err != nil {
				return err
			}
			if change.TxNum != posting.txNum || !bytes.Equal(stateDomainChangeBinaryAccessorKey(change), record.key) {
				return errors.New("snapshots: V7 accessor posting does not match history record")
			}
			cont, err := fn(change)
			if err != nil || !cont {
				return err
			}
		}
		previous, havePrevious = frame, true
	}
	return nil
}

func iterateStateDomainChangeBinarySegmentByAccessorV7Key(segment io.ReaderAt, segmentSize uint64, accessor io.ReaderAt, accessorSize uint64, lookupKey []byte, fromTxNum, toTxNum uint64, fn func(*rawdb.StateDomainChange) (bool, error)) error {
	if err := verifyStateDomainChangeBinaryKeyDictionaryPair(segment, accessor, accessorSize); err != nil {
		return err
	}
	h, record, ok, err := stateDomainChangeBinaryAccessorV7Lookup(accessor, accessorSize, lookupKey)
	if err != nil || !ok {
		return err
	}
	return iterateStateDomainChangeBinarySegmentByAccessorV7Record(segment, segmentSize, accessor, h, record, fromTxNum, toTxNum, fn)
}

func iterateStateDomainChangeBinarySegmentByAccessorV7KeysContext(ctx context.Context, segment io.ReaderAt, segmentSize uint64, accessor io.ReaderAt, accessorSize uint64, lookupKeys [][]byte, fromTxNum, toTxNum uint64, fn func([]byte, *rawdb.StateDomainChange) (bool, error)) error {
	if len(lookupKeys) == 0 {
		return nil
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := verifyStateDomainChangeBinaryKeyDictionaryPair(segment, accessor, accessorSize); err != nil {
		return err
	}
	h, err := decodeStateDomainChangeBinaryAccessorV7Header(accessor, accessorSize)
	if err != nil {
		return err
	}
	keys := make([][]byte, len(lookupKeys))
	copy(keys, lookupKeys)
	sort.Slice(keys, func(i, j int) bool { return bytes.Compare(keys[i], keys[j]) < 0 })
	// A production accessor can contain tens of thousands of key blocks. Do
	// not eagerly read its full directory for a batch of roughly one hundred
	// dynamic-property keys: on a compressed reader that turns a point lookup
	// into a multi-gigabyte directory walk. Cache only directory entries touched
	// by binary searches and key blocks that actually contain requested keys.
	pages := acquireHistoryDirectoryPages(ctx, accessor, h.headerSize, h.blockDirLen)
	defer releaseHistoryDirectoryPages(pages)
	directory := make(map[uint64]stateDomainChangeBinaryAccessorV6Block)
	readDirectory := func(index uint64) (stateDomainChangeBinaryAccessorV6Block, error) {
		if block, ok := directory[index]; ok {
			return block, nil
		}
		block, err := stateDomainChangeBinaryAccessorV6ReadBlockDirectoryEntry(pages, h, index)
		if err == nil {
			directory[index] = block
		}
		return block, err
	}
	var offsets *historyAccessorOffsetResolver
	if isHistoryOffsetAccessor(h.version) {
		offsets = newHistoryAccessorOffsetResolver(accessor, h)
	}
	recordBlocks := make(map[uint64][]stateDomainChangeBinaryAccessorV6Record)
	for _, lookupKey := range keys {
		if err := ctx.Err(); err != nil {
			return err
		}
		var blockIndex uint64
		if isHistoryInlineAccessor(h.version) {
			block, index, found, err := findHistoryAccessorKeyBlock(pages, h, lookupKey)
			if err != nil {
				return err
			}
			if !found {
				continue
			}
			blockIndex = index
			directory[index] = block
		} else {
			low, high := uint64(0), h.blockCount
			for low < high {
				mid := low + (high-low)/2
				block, err := readDirectory(mid)
				if err != nil {
					return err
				}
				if bytes.Compare(block.firstKey, lookupKey) <= 0 {
					low = mid + 1
				} else {
					high = mid
				}
			}
			if low == 0 {
				continue
			}
			blockIndex = low - 1
		}
		records, ok := recordBlocks[blockIndex]
		if !ok {
			block, err := readDirectory(blockIndex)
			if err != nil {
				return err
			}
			records, err = stateDomainChangeBinaryAccessorV6ReadBlock(accessor, accessorSize, h, block, uint32(blockIndex*stateDomainChangeBinaryAccessorV6BlockKeys))
			if err != nil {
				return err
			}
			recordBlocks[blockIndex] = records
		}
		pos := sort.Search(len(records), func(i int) bool { return bytes.Compare(records[i].key, lookupKey) >= 0 })
		if pos == len(records) || !bytes.Equal(records[pos].key, lookupKey) {
			continue
		}
		if err := iterateStateDomainChangeBinarySegmentByAccessorV7Record(segment, segmentSize, accessor, h, records[pos], fromTxNum, toTxNum, func(change *rawdb.StateDomainChange) (bool, error) {
			if err := ctx.Err(); err != nil {
				return false, err
			}
			return fn(lookupKey, change)
		}, offsets); err != nil {
			return err
		}
	}
	return ctx.Err()
}

func iterateStateDomainChangeBinarySegmentByAccessorV7Prefix(segment io.ReaderAt, segmentSize uint64, accessor io.ReaderAt, accessorSize uint64, lookupPrefix []byte, fromTxNum, toTxNum uint64, fn func(*rawdb.StateDomainChange) (bool, error)) error {
	if err := verifyStateDomainChangeBinaryKeyDictionaryPair(segment, accessor, accessorSize); err != nil {
		return err
	}
	h, err := decodeStateDomainChangeBinaryAccessorV7Header(accessor, accessorSize)
	if err != nil {
		return err
	}
	_, start, _, err := findHistoryAccessorKeyBlock(accessor, h, lookupPrefix)
	if err != nil {
		return err
	}

	var offsets *historyAccessorOffsetResolver
	if isHistoryOffsetAccessor(h.version) {
		offsets = newHistoryAccessorOffsetResolver(accessor, h)
	}
	for blockIndex := start; blockIndex < h.blockCount; blockIndex++ {
		block, err := stateDomainChangeBinaryAccessorV6ReadBlockDirectoryEntry(accessor, h, blockIndex)
		if err != nil {
			return err
		}
		records, err := stateDomainChangeBinaryAccessorV6ReadBlock(accessor, accessorSize, h, block, uint32(blockIndex*stateDomainChangeBinaryAccessorV6BlockKeys))
		if err != nil {
			return err
		}
		for _, record := range records {
			if bytes.Compare(record.key, lookupPrefix) < 0 {
				continue
			}
			if !bytes.HasPrefix(record.key, lookupPrefix) {
				return nil
			}
			if err := iterateStateDomainChangeBinarySegmentByAccessorV7Record(segment, segmentSize, accessor, h, record, fromTxNum, toTxNum, fn, offsets); err != nil {
				return err
			}
		}
	}
	return nil
}

func verifyStateDomainChangeBinaryKeyDictionaryPair(segment, accessor io.ReaderAt, accessorSize uint64) error {
	h, err := decodeStateDomainChangeBinaryAccessorKeyHeader(accessor, accessorSize)
	if err != nil {
		return err
	}
	digest, err := readStateDomainChangeBinaryV6DictionaryCommitment(segment)
	if err != nil {
		return err
	}
	if digest != h.dictionaryDigest {
		return errors.New("snapshots: history/accessor dictionary commitment mismatch")
	}
	return nil
}

func checkStateDomainChangeBinaryAccessorV7(r io.ReaderAt, fileSize uint64) error {
	h, err := decodeStateDomainChangeBinaryAccessorV7Header(r, fileSize)
	if err != nil {
		return err
	}
	blocks, err := stateDomainChangeBinaryAccessorV6ReadBlockDirectory(r, h)
	if err != nil {
		return err
	}
	if err := verifyHistoryAccessorSparseDirectory(r, h, blocks); err != nil {
		return err
	}
	if err := checkHistoryAccessorOffsets(r, h); err != nil {
		return err
	}
	if err := checkHistoryOwnerDictionary(r, h); err != nil {
		return err
	}
	var keys, postings uint64
	var previous []byte
	var expectedOff uint64
	for blockIndex, block := range blocks {
		records, err := stateDomainChangeBinaryAccessorV6ReadBlock(r, fileSize, h, block, uint32(blockIndex*stateDomainChangeBinaryAccessorV6BlockKeys))
		if err != nil {
			return err
		}
		for _, record := range records {
			if previous != nil && bytes.Compare(previous, record.key) >= 0 {
				return errors.New("snapshots: V7 accessor dictionary is not sorted")
			}
			if !record.inline && record.postingOff != expectedOff {
				return errors.New("snapshots: V7 accessor postings are not contiguous")
			}
			frames, err := stateDomainChangeBinaryAccessorV7PostingFrames(r, h, record)
			if err != nil {
				return err
			}
			var last stateDomainChangeBinaryAccessorV6Posting
			var seen uint64
			var postingListLength uint64
			for _, frame := range frames {
				rows, frameEnd, err := readHistoryAccessorRawFrame(r, h, record, frame)
				if err != nil {
					return err
				}
				postingListLength = max(postingListLength, frameEnd)
				for _, p := range rows {
					if p.txNum < h.fromTxNum || p.txNum > h.toTxNum || uint64(p.recordIndex) >= h.recordCount {
						return errors.New("snapshots: V7 accessor posting outside segment bounds")
					}
					if seen > 0 && (p.txNum < last.txNum || !isHistoryOffsetAccessor(h.version) && p.offset <= last.offset || p.recordIndex <= last.recordIndex) {
						return errors.New("snapshots: V7 accessor postings are not ordered")
					}
					last = p
					seen++
				}
			}
			if seen != uint64(record.postings) {
				return errors.New("snapshots: V7 accessor posting count mismatch")
			}
			expectedOff += postingListLength
			postings += seen
			keys++
			previous = record.key
		}
	}
	if keys != h.keyCount || postings != h.recordCount || expectedOff != h.postingLen {
		return fmt.Errorf("snapshots: V7 accessor counts keys=%d/%d postings=%d/%d bytes=%d/%d", keys, h.keyCount, postings, h.recordCount, expectedOff, h.postingLen)
	}
	return nil
}

func stateDomainChangeBinaryAccessorV7PostingListLength(r io.ReaderAt, h stateDomainChangeBinaryAccessorV6Header, record stateDomainChangeBinaryAccessorV6Record) (uint64, error) {
	if record.inline {
		return 0, nil
	}
	frames, err := stateDomainChangeBinaryAccessorV7PostingFrames(r, h, record)
	if err != nil {
		return 0, err
	}
	if len(frames) == 1 && frames[0].dataOff == 1 {
		scratch := stateDomainChangeBinaryAccessorV7SingleReadBufferPool.Get().(*stateDomainChangeBinaryAccessorV7SingleReadBuffer)
		defer stateDomainChangeBinaryAccessorV7SingleReadBufferPool.Put(scratch)
		_, length, err := stateDomainChangeBinaryAccessorV7ReadSingleFrameData(r, h, record, frames[0].count, scratch[:])
		return length, err
	}
	last := frames[len(frames)-1]
	return uint64(last.dataOff) + uint64(last.dataLen), nil
}

func readStateDomainChangeBinaryAccessorV7Debug(accessor io.ReaderAt, accessorSize uint64) ([]stateDomainChangeBinaryAccessorEntry, error) {
	h, err := decodeStateDomainChangeBinaryAccessorV7Header(accessor, accessorSize)
	if err != nil {
		return nil, err
	}
	blocks, err := stateDomainChangeBinaryAccessorV6ReadBlockDirectory(accessor, h)
	if err != nil {
		return nil, err
	}
	entries := make([]stateDomainChangeBinaryAccessorEntry, 0, h.recordCount)
	for bi, b := range blocks {
		records, err := stateDomainChangeBinaryAccessorV6ReadBlock(accessor, accessorSize, h, b, uint32(bi*stateDomainChangeBinaryAccessorV6BlockKeys))
		if err != nil {
			return nil, err
		}
		for _, record := range records {
			frames, err := stateDomainChangeBinaryAccessorV7PostingFrames(accessor, h, record)
			if err != nil {
