				}
				for _, p := range rows {
					entries = append(entries, stateDomainChangeBinaryAccessorEntry{key: append([]byte(nil), record.key...), txNum: p.txNum, seq: uint64(p.recordIndex) + 1, offset: p.offset, recordIndex: uint64(p.recordIndex)})
				}
			}
		}
	}
	sort.Slice(entries, func(i, j int) bool { return compareStateDomainChangeBinaryAccessorEntry(entries[i], entries[j]) < 0 })
	return entries, nil
}

package snapshots

import (
	"bufio"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"io"
	"math"
	"os"
)

const stateDomainChangeBinaryAccessorVersionV9 = uint32(9)
const historyOffsetPageRows = uint64(128)
const historyOffsetEntrySize = uint64(12)
const historyOffsetFooterSize = uint64(32)
const historyOffsetPageMaxBytes = 6 + 127*binary.MaxVarintLen64
const historyOffsetCachePages = 64

var historyOffsetMagic = [8]byte{'G', 'T', 'O', 'F', 'F', 'S', '0', '9'}

func isHistoryInlineAccessor(version uint32) bool {
	return version == stateDomainChangeBinaryAccessorVersionV8 || isHistoryOffsetAccessor(version)
}

func isHistoryOffsetAccessor(version uint32) bool {
	return version == stateDomainChangeBinaryAccessorVersionV9 || version == stateDomainChangeBinaryAccessorVersionV10
}

func historyOffsetCRC(page uint64, entry, payload []byte) uint32 {
	var index [8]byte
	binary.BigEndian.PutUint64(index[:], page)
	c := crc32.ChecksumIEEE(index[:])
	c = crc32.Update(c, crc32.IEEETable, entry[:8])
	return crc32.Update(c, crc32.IEEETable, payload)
}

func decodeHistoryOffsetFooter(r io.ReaderAt, size, postingEnd uint64, h *stateDomainChangeBinaryAccessorV6Header) error {
	if size < historyOffsetFooterSize || postingEnd > size-historyOffsetFooterSize {
		return errors.New("snapshots: truncated V9 offset locator")
	}
	var raw [historyOffsetFooterSize]byte
	if _, err := r.ReadAt(raw[:], int64(size-historyOffsetFooterSize)); err != nil {
		return err
	}
	if string(raw[:8]) != string(historyOffsetMagic[:]) || binary.BigEndian.Uint64(raw[8:16]) != h.recordCount || binary.BigEndian.Uint32(raw[24:28]) != uint32(historyOffsetPageRows) || binary.BigEndian.Uint32(raw[28:]) != crc32.ChecksumIEEE(raw[:28]) {
		return errors.New("snapshots: invalid V9 offset locator footer")
	}
	h.offsetDataBase = postingEnd
	h.offsetDataLen = binary.BigEndian.Uint64(raw[16:24])
	dirLen := ceilDiv(h.recordCount, historyOffsetPageRows) * historyOffsetEntrySize
	remaining := size - historyOffsetFooterSize - postingEnd
	if h.offsetDataLen > remaining || remaining-h.offsetDataLen != dirLen || h.recordCount == 0 && h.offsetDataLen != 0 {
		return errors.New("snapshots: invalid V9 offset locator size")
	}
	h.offsetDirectory = postingEnd + h.offsetDataLen
	return nil
}

func decodeHistoryOffsetPage(h stateDomainChangeBinaryAccessorV6Header, page uint64, entry, raw []byte) ([]uint64, error) {
	if len(entry) != int(historyOffsetEntrySize) || len(raw) < 6 || len(raw) > historyOffsetPageMaxBytes || historyOffsetCRC(page, entry, raw) != binary.BigEndian.Uint32(entry[8:]) {
		return nil, errors.New("snapshots: V9 offset page checksum/length mismatch")
	}
	if page >= ceilDiv(h.recordCount, historyOffsetPageRows) {
		return nil, errors.New("snapshots: V9 offset page outside record count")
	}
	count := min(historyOffsetPageRows, h.recordCount-page*historyOffsetPageRows)
	first, err := stateDomainChangeBinaryAccessorV5Offset(raw[:6])
	if err != nil {
		return nil, err
	}
	offsets := make([]uint64, count)
	offsets[0] = first
	pos := 6
	for i := uint64(1); i < count; i++ {
		delta, n := binary.Uvarint(raw[pos:])
		if n <= 0 || delta == 0 || delta > stateDomainChangeBinaryAccessorV5MaxOffset-offsets[i-1] {
			return nil, errors.New("snapshots: invalid V9 offset page delta")
		}
		pos += n
		offsets[i] = offsets[i-1] + delta
	}
	if pos != len(raw) {
		return nil, errors.New("snapshots: V9 offset page trailing bytes")
	}
	return offsets, nil
}

func historyOffsetEntryBounds(h stateDomainChangeBinaryAccessorV6Header, raw []byte) (uint64, uint64, error) {
	off, err := stateDomainChangeBinaryAccessorV5Offset(raw[:6])
	n := uint64(binary.BigEndian.Uint16(raw[6:8]))
	if err != nil || off > h.offsetDataLen || n < 6 || n > historyOffsetPageMaxBytes || n > h.offsetDataLen-off {
		return 0, 0, errors.New("snapshots: V9 offset page outside payload")
	}
	return off, n, nil
}

// The cache is private to one iterator/request; immutable decoded pages only.
type historyAccessorOffsetResolver struct {
	r     io.ReaderAt
	h     stateDomainChangeBinaryAccessorV6Header
	pages map[uint64][]uint64
	order []uint64
}

func newHistoryAccessorOffsetResolver(r io.ReaderAt, h stateDomainChangeBinaryAccessorV6Header) *historyAccessorOffsetResolver {
	return &historyAccessorOffsetResolver{r: r, h: h, pages: make(map[uint64][]uint64)}
}

func (r *historyAccessorOffsetResolver) Offset(ordinal uint32) (uint64, error) {
	if uint64(ordinal) >= r.h.recordCount {
		return 0, errors.New("snapshots: V9 locator ordinal outside segment")
	}
	page := uint64(ordinal) / historyOffsetPageRows
	values, ok := r.pages[page]
	if !ok {
		var entry [historyOffsetEntrySize]byte
		if _, err := r.r.ReadAt(entry[:], int64(r.h.offsetDirectory+page*historyOffsetEntrySize)); err != nil {
			return 0, err
		}
		off, n, err := historyOffsetEntryBounds(r.h, entry[:])
		if err != nil {
			return 0, err
		}
		raw := make([]byte, n)
		if _, err := r.r.ReadAt(raw, int64(r.h.offsetDataBase+off)); err != nil {
			return 0, err
		}
		values, err = decodeHistoryOffsetPage(r.h, page, entry[:], raw)
		if err != nil {
			return 0, err
		}
		if len(r.order) == historyOffsetCachePages {
			delete(r.pages, r.order[0])
			r.order = r.order[1:]
		}
		r.pages[page] = values
		r.order = append(r.order, page)
	}
	return values[uint64(ordinal)%historyOffsetPageRows], nil
}

// Full verification walks directory/payload in order, never one random read per row.
func checkHistoryAccessorOffsets(r io.ReaderAt, h stateDomainChangeBinaryAccessorV6Header) error {
	if !isHistoryOffsetAccessor(h.version) {
		return nil
	}
	count := ceilDiv(h.recordCount, historyOffsetPageRows)
	directory := bufio.NewReaderSize(io.NewSectionReader(r, int64(h.offsetDirectory), int64(count*historyOffsetEntrySize)), 64<<10)
	data := bufio.NewReaderSize(io.NewSectionReader(r, int64(h.offsetDataBase), int64(h.offsetDataLen)), 1<<20)
	var next, previous uint64
	var entry [historyOffsetEntrySize]byte
	var payload [historyOffsetPageMaxBytes]byte
	for page := uint64(0); page < count; page++ {
		if _, err := io.ReadFull(directory, entry[:]); err != nil {
			return err
		}
		off, n, err := historyOffsetEntryBounds(h, entry[:])
		if err != nil {
			return err
		}
		if off != next {
			return errors.New("snapshots: V9 offset pages are not contiguous")
		}
		if _, err := io.ReadFull(data, payload[:n]); err != nil {
			return err
		}
		values, err := decodeHistoryOffsetPage(h, page, entry[:], payload[:n])
		if err != nil {
			return err
		}
		if page > 0 && values[0] <= previous {
			return errors.New("snapshots: V9 offset pages are not ordered")
		}
		previous, next = values[len(values)-1], off+n
	}
	if next != h.offsetDataLen {
		return errors.New("snapshots: V9 offset payload coverage mismatch")
	}
	return nil
}

type historyAccessorOffsetBuilder struct {
	data, directory             *os.File
	dataName, directoryName     string
	dataWriter, directoryWriter *bufio.Writer
	page                        [historyOffsetPageRows]uint64
	rows, bytes                 uint64
	used                        int
	last                        uint64
}

func newHistoryAccessorOffsetBuilder(dir, base string) (*historyAccessorOffsetBuilder, error) {
	b := new(historyAccessorOffsetBuilder)
	var err error
	b.data, b.dataName, err = createStateDomainChangeBinaryTempFileInDir(dir, base+".offset-data")
	if err != nil {
		return nil, err
	}
	b.directory, b.directoryName, err = createStateDomainChangeBinaryTempFileInDir(dir, base+".offset-directory")
	if err != nil {
		b.Close()
		return nil, err
	}
	b.dataWriter = bufio.NewWriterSize(b.data, 1<<20)
	b.directoryWriter = bufio.NewWriterSize(b.directory, 64<<10)
	return b, nil
}

func (b *historyAccessorOffsetBuilder) Close() {
	if b == nil {
		return
	}
	for _, f := range []*os.File{b.data, b.directory} {
		if f != nil {
			_ = f.Close()
		}
	}
	for _, n := range []string{b.dataName, b.directoryName} {
		if n != "" {
			_ = os.Remove(n)
		}
	}
}

func (b *historyAccessorOffsetBuilder) Add(ordinal, offset uint64) error {
	if ordinal != b.rows || ordinal > math.MaxUint32 || offset > stateDomainChangeBinaryAccessorV5MaxOffset || b.rows > 0 && offset <= b.last {
		return errors.New("snapshots: V9 locator input is not in ordinal/offset order")
	}
	b.page[b.used] = offset
	b.used++
	b.rows++
	b.last = offset
	if b.used == int(historyOffsetPageRows) {
		return b.flushPage()
	}
	return nil
}

func (b *historyAccessorOffsetBuilder) flushPage() error {
	if b.used == 0 {
		return nil
	}
	var payload [historyOffsetPageMaxBytes]byte
	if err := putStateDomainChangeBinaryAccessorV5Offset(payload[:6], b.page[0]); err != nil {
		return err
	}
	raw := payload[:6]
	for i := 1; i < b.used; i++ {
		raw = binary.AppendUvarint(raw, b.page[i]-b.page[i-1])
	}
	var entry [historyOffsetEntrySize]byte
	if err := putStateDomainChangeBinaryAccessorV5Offset(entry[:6], b.bytes); err != nil {
		return err
	}
	binary.BigEndian.PutUint16(entry[6:8], uint16(len(raw)))
	page := (b.rows - 1) / historyOffsetPageRows
	binary.BigEndian.PutUint32(entry[8:], historyOffsetCRC(page, entry[:], raw))
	if _, err := b.dataWriter.Write(raw); err != nil {
		return err
	}
	if _, err := b.directoryWriter.Write(entry[:]); err != nil {
		return err
	}
	b.bytes += uint64(len(raw))
	b.used = 0
	return nil
}

func (b *historyAccessorOffsetBuilder) AppendTo(w io.Writer, count uint64) error {
	if b.rows != count {
		return errors.New("snapshots: V9 offset builder record count mismatch")
	}
	if err := b.flushPage(); err != nil {
		return err
	}
	if err := b.dataWriter.Flush(); err != nil {
		return err
	}
	if err := b.directoryWriter.Flush(); err != nil {
		return err
	}
	for _, f := range []*os.File{b.data, b.directory} {
		if _, err := f.Seek(0, io.SeekStart); err != nil {
			return err
		}
		if _, err := copyStateDomainChangeHistoryData(w, f); err != nil {
			return err
		}
	}
	var footer [historyOffsetFooterSize]byte
	copy(footer[:8], historyOffsetMagic[:])
	binary.BigEndian.PutUint64(footer[8:16], count)
	binary.BigEndian.PutUint64(footer[16:24], b.bytes)
	binary.BigEndian.PutUint32(footer[24:28], uint32(historyOffsetPageRows))
	binary.BigEndian.PutUint32(footer[28:], crc32.ChecksumIEEE(footer[:28]))
	_, err := w.Write(footer[:])
	return err
}

core/state/snapshots/history_v10_test.go.text:
package snapshots

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sort"
	"testing"

	"github.com/tronprotocol/go-tron/common"
	"github.com/tronprotocol/go-tron/core/rawdb"
	"github.com/tronprotocol/go-tron/core/rawdb/etl"
)

func ownerFixtureKeys(count int, repeated bool) [][]byte {
	owners := make([][20]byte, count)
	for i := range owners {
		sum := sha256.Sum256([]byte(fmt.Sprintf("owner/%d", i)))
		copy(owners[i][:], sum[:20])
	}
	sort.Slice(owners, func(i, j int) bool { return bytes.Compare(owners[i][:], owners[j][:]) < 0 })
	var keys [][]byte
	for _, owner := range owners {
		keys = append(keys, append([]byte{1}, owner[:]...))
	}
	if repeated {
		for _, owner := range owners {
			key := make([]byte, 39)
			key[0] = 2
			copy(key[1:21], owner[:])
			binary.BigEndian.PutUint64(key[21:29], 1)
			binary.BigEndian.PutUint16(key[29:31], 515)
			copy(key[31:], []byte("1002000"))
			keys = append(keys, key)
		}
	}
	return keys
}

func buildOwnerAccessorFixture(t testing.TB, version uint32, count int, repeated bool) ([]byte, []v8ExpectedKey) {
	t.Helper()
	dir := t.TempDir()
	b, err := newStateDomainChangeV6Build(etl.Options{TempDir: t.TempDir()}, dir, "owners")
	if err != nil {
		t.Fatal(err)
	}
	defer b.Close()
	keys := ownerFixtureKeys(count, repeated)
	expected := make([]v8ExpectedKey, len(keys))
	for i, key := range keys {
		expected[i].key = key
		if err := b.CollectLogicalKey(key); err != nil {
			t.Fatal(err)
		}
	}
	if err := b.FinishDictionary(); err != nil {
		t.Fatal(err)
	}
	var ordinal uint32
	for i := range expected {
		count := 1
		if i%47 == 0 {
			count = 129
		}
		for j := 0; j < count; j++ {
			p := stateDomainChangeBinaryAccessorV6Posting{txNum: 10 + uint64(i), offset: 100 + uint64(ordinal)*37, recordIndex: ordinal}
			ordinal++
			expected[i].rows = append(expected[i].rows, p)
			if err := b.CollectPosting(uint32(i), p.txNum, p.offset, uint64(p.recordIndex)); err != nil {
				t.Fatal(err)
			}
		}
	}
	ref, _, err := b.buildAccessorContextVersion(context.Background(), dir, SegmentRef{Dataset: SegmentDatasetStateDomainChange, Kind: SegmentAccessor, Path: "history/fixture.kv", FromTxNum: 10, ToTxNum: 10 + uint64(len(keys))}, uint64(ordinal), version)
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(dir, ref.Path))
	if err != nil {
		t.Fatal(err)
	}
	return data, expected
}

func TestHistoryOwnerRoundTripAndFallback(t *testing.T) {
	for _, version := range []uint32{7, 8, 9, 10} {
		t.Run(fmt.Sprint(version), func(t *testing.T) {
			data, expected := buildOwnerAccessorFixture(t, version, 4200, true)
			r := bytes.NewReader(data)
			h, err := decodeStateDomainChangeBinaryAccessorKeyHeader(r, uint64(len(data)))
			if err != nil {
				t.Fatal(err)
			}
			if h.version != version {
				t.Fatalf("wanted V%d got %d", version, h.version)
			}
			if err := checkStateDomainChangeBinaryAccessorV7(r, uint64(len(data))); err != nil {
				t.Fatal(err)
			}
			cursor, err := newStateDomainChangeBinaryAccessorV7PostingCursor(r, uint64(len(data)))
			if err != nil {
				t.Fatal(err)
			}
			for i, e := range expected {
				// Exercise every reconstructed dictionary ID and the batched page cursor.
				key, err := stateDomainChangeBinaryAccessorV6KeyByID(r, uint64(len(data)), uint32(i))
				if err != nil || !bytes.Equal(key, e.key) {
					t.Fatal(i, "key identity", err)
				}
				if i%127 == 0 {
					_, rec, ok, err := stateDomainChangeBinaryAccessorV7Lookup(r, uint64(len(data)), e.key)
					if err != nil || !ok || rec.keyID != uint32(i) {
						t.Fatal(i, "lookup", ok, err)
					}
				}
				for _, want := range e.rows {
					id, p, ok, err := cursor.Next()
					if err != nil || !ok || id != uint32(i) || p != want {
						t.Fatal(i, id, p, want, ok, err)
					}
				}
			}
			if _, _, ok, err := cursor.Next(); err != nil || ok {
				t.Fatal("cursor end", ok, err)
			}
			if version == 10 {
				t.Logf("V10 keys=%d ownerPages=%d bytes=%d", h.keyCount, ceilDiv(h.owners.count, 128), len(data))
			}
		})
	}
	for _, count := range []int{1, 127, 129, 4200} {
		a, _ := buildOwnerAccessorFixture(t, 9, count, false)
		b, _ := buildOwnerAccessorFixture(t, 10, count, false)
		if !bytes.Equal(a, b) {
			t.Fatal("nonrepeated owners must retain exact V9 when dictionary is not profitable", count, len(a), len(b))
		}
	}
	a, _ := buildAccessorVersionFixture(t, 9, 4200)
	b, _ := buildAccessorVersionFixture(t, 10, 4200)
	if !bytes.Equal(a, b) {
		t.Fatal("generic keys fallback changed bytes")
	}
}

func TestHistoryOwnerBoundsCorruptionCancellation(t *testing.T) {
	data, _ := buildOwnerAccessorFixture(t, 10, 512, true)
	r := bytes.NewReader(data)
	h, err := decodeStateDomainChangeBinaryAccessorKeyHeader(r, uint64(len(data)))
	if err != nil || h.owners == nil {
		t.Fatal(h, err)
	}
	for _, at := range []uint64{h.owners.prefixSize, h.owners.prefixSize + h.owners.dataLen, uint64(len(data)) - 1} {
		bad := append([]byte(nil), data...)
		bad[at] ^= 1
		if err := checkStateDomainChangeBinaryAccessorV7(bytes.NewReader(bad), uint64(len(bad))); err == nil {
			t.Fatal("corruption accepted", at)
		}
	}
	for _, count := range []uint64{0, 1<<20 + 1, ^uint64(0)} {
		bad := append([]byte(nil), data...)
		footer := bad[len(bad)-64:]
		binary.BigEndian.PutUint64(footer[8:16], count)
		binary.BigEndian.PutUint32(footer[60:], crc32.ChecksumIEEE(footer[:60]))
		if _, err := decodeStateDomainChangeBinaryAccessorKeyHeader(bytes.NewReader(bad), uint64(len(bad))); err == nil {
			t.Fatal("invalid owner count", count)
		}
	}
	for _, cut := range []int{1, 12, 63, 64} {
		bad := data[:len(data)-cut]
		if _, err := decodeStateDomainChangeBinaryAccessorKeyHeader(bytes.NewReader(bad), uint64(len(bad))); err == nil {
			t.Fatal("truncated dictionary", cut)
		}
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := makeHistoryOwnerTableContext(ctx, [][20]byte{{}}); !errors.Is(err, context.Canceled) {
		t.Fatal("table cancellation", err)
	}
	_, _, _, err = stateDomainChangeBinaryAccessorV7Lookup(contextReaderAt{ctx: ctx, r: r}, uint64(len(data)), []byte{1})
	if !errors.Is(err, context.Canceled) {
		t.Fatal("lookup cancellation", err)
	}
	entry := make([]byte, 18)
	binary.BigEndian.PutUint32(entry[6:10], ^uint32(0))
	binary.BigEndian.PutUint32(entry[10:14], ^uint32(0))
	if _, _, _, err := historyOwnerPageBounds(h.owners, 0, entry); err == nil {
		t.Fatal("oversized owner payload")
	}
	// Even a forged valid CRC cannot bypass the per-key-page four-owner-page bound.
	recs := make([]stateDomainChangeBinaryAccessorV6Record, 5)
	for i := range recs {
		recs[i].key = make([]byte, 5)
		binary.BigEndian.PutUint32(recs[i].key[1:], uint32(i*128))
	}
	fake := h
	copyHeader := *h.owners
	copyHeader.count = 640
	fake.owners = &copyHeader
	counted := &v9CountedReader{Reader: r}
	if err := resolveHistoryOwnerKeys(counted, fake, recs); err == nil || counted.calls != 0 {
		t.Fatal("unbounded owner reads", counted.calls, err)
	}
}

func TestHistoryOwnerSparsePagesRemainPlain(t *testing.T) {
	owners := make([][20]byte, 8192)
	for i := range owners {
		binary.BigEndian.PutUint32(owners[i][16:], uint32(i))
	}
	table, err := makeHistoryOwnerTable(owners)
	if err != nil {
		t.Fatal(err)
	}
	keys := make([]stateDomainChangeBinaryAccessorV6Key, 128)
	for i := range keys {
		keys[i] = stateDomainChangeBinaryAccessorV6Key{key: append([]byte{1}, owners[i*64][:]...), postingCount: 1, inlinePosting: stateDomainChangeBinaryAccessorV6Posting{txNum: 10, offset: 100 + uint64(i)*37, recordIndex: uint32(i)}}
	}
	largest := 0
	raw, _, _, err := encodeHistoryOwnerKeyBlock(keys, 10, table, &largest)
	if err != nil || raw[0] != 0 {
		t.Fatal("sparse page must retain canonical keys", err)
	}
}

func TestHistoryOwnerStrictCoverageRejectsForgedDictionary(t *testing.T) {
	dir := t.TempDir()
	db := rawdb.NewMemoryDatabase()
	hash := common.Hash{31: 1}
	if err := rawdb.WriteStateTxRange(db, 1, hash, 1, 1); err != nil {
		t.Fatal(err)
	}
	keys := ownerFixtureKeys(512, true)
	for i, key := range keys {
		owner := common.Address{0: common.AddressPrefixMainnet}
		copy(owner[1:], key[1:21])
		change := &rawdb.StateDomainChange{BlockNum: 1, BlockHash: hash, TxNum: 1, Seq: uint64(i + 1), FlatDomain: rawdb.StateFlatDomain(key[0]), Owner: owner, PrevExists: true, Prev: []byte{1}}
		if key[0] == 2 {
			change.Generation = 1
			change.Domain = 515
			change.Key = key[31:]
		}
		if err := rawdb.WriteStateDomainChange(db, change); err != nil {
			t.Fatal(err)
		}
	}
	refs, err := BuildStateDomainChangeHistorySegmentsFromDB(db, dir, 1, 1, "history/state-domain-change-forged-owner.seg")
	if err != nil {
		t.Fatal(err)
	}
	var history, index, accessor SegmentRef
	for _, ref := range refs {
		switch ref.Kind {
		case SegmentHistory:
			history = ref
		case SegmentInverted:
			index = ref
		case SegmentAccessor:
			accessor = ref
		}
	}
	check := func() error {
		return verifyStateDomainChangeBinaryCompanionsAgainstSegmentContext(context.Background(), dir, history, index, accessor)
	}
	if err := check(); err != nil {
		t.Fatal("valid companions", err)
	}
	path := filepath.Join(dir, accessor.Path)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	h, err := decodeStateDomainChangeBinaryAccessorKeyHeader(bytes.NewReader(data), uint64(len(data)))
	if err != nil || h.owners == nil {
		t.Fatal(h, err)
	}
	entry := data[h.owners.prefixSize+h.owners.dataLen : h.owners.prefixSize+h.owners.dataLen+18]
	off, n, flags, err := historyOwnerPageBounds(h.owners, 0, entry)
	if err != nil || flags&stateDomainChangeBinaryAccessorV6StoredRaw == 0 {
		t.Fatal("raw first dictionary page fixture", err)
	}
	payload := data[h.owners.prefixSize+off : h.owners.prefixSize+off+n]
	// Owner #1 is not a key-page first key. Perturb its last suffix byte while
	// preserving sorted order, then forge both physical checksums and key digest.
	pos := 21
	prefix := int(payload[pos])
	pos++
	payload[pos+20-prefix-1] ^= 1
	binary.BigEndian.PutUint32(entry[14:], historyOwnerPageCRC(0, entry, payload))
	blocks, err := stateDomainChangeBinaryAccessorV6ReadBlockDirectory(bytes.NewReader(data), h)
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.New()
	for bi, b := range blocks {
		records, err := stateDomainChangeBinaryAccessorV6ReadBlock(bytes.NewReader(data), uint64(len(data)), h, b, uint32(bi*128))
		if err != nil {
			t.Fatal("forged expanded keys", err)
		}
		for _, rec := range records {
			var length [4]byte
			binary.BigEndian.PutUint32(length[:], uint32(len(rec.key)))
			digest.Write(length[:])
			digest.Write(rec.key)
		}
	}
	copy(data[72:104], digest.Sum(nil))
	binary.BigEndian.PutUint32(data[112:116], stateDomainChangeAccessorHeaderCRC(data, 10))
	if err := checkStateDomainChangeBinaryAccessorV7(bytes.NewReader(data), uint64(len(data))); err != nil {
		t.Fatal("forgery must be structurally well formed", err)
	}
	if err := os.WriteFile(path, data, 0600); err != nil {
		t.Fatal(err)
	}
	accessor.Checksum = fmt.Sprintf("sha256:%x", sha256.Sum256(data))
	accessor.Size = uint64(len(data))
	if err := check(); err == nil {
		t.Fatal("accepted owner mapping not matching authoritative history")
	}
}

core/state/snapshots/history_v10_transco.text:
package snapshots

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"hash/crc32"
	"reflect"
	"testing"
)

type accessorV10TranscodeAudit struct {
	Keys, Records, Owners, CompactPages, PlainPages                uint64
	SourceBytes, CandidateBytes, SourceKeyBytes, CandidateKeyBytes uint64
	OwnerDataBytes, OwnerDirectoryBytes, OwnerFooterBytes          uint64
	PostingBytes, OffsetBytes, DirectoryBytes                      uint64
	AccountKeys, AssetKeys, CrossFlatOwners                        uint64
	Version                                                        uint32
	DictionaryDigest                                               [32]byte
}

// Bounded test-only transformation. Posting and locator sections are copied
// byte-for-byte; every expanded key/ID and inline/posting metadata is compared.
func transcodeHistoryAccessorV10ForTest(data []byte) ([]byte, accessorV10TranscodeAudit, error) {
	var audit accessorV10TranscodeAudit
	if len(data) > 128<<20 {
		return nil, audit, fmt.Errorf("offline V10 input exceeds 128 MiB")
	}
	r := bytes.NewReader(data)
	h, err := decodeStateDomainChangeBinaryAccessorKeyHeader(r, uint64(len(data)))
	if err != nil {
		return nil, audit, err
	}
	if h.version != 9 || h.keyCount > 1<<20 {
		return nil, audit, fmt.Errorf("offline V10 requires bounded V9 input")
	}
	blocks, err := stateDomainChangeBinaryAccessorV6ReadBlockDirectory(r, h)
	if err != nil {
		return nil, audit, err
	}
	seen := map[[20]byte]byte{}
	eligible := h.keyCount >= 128
	for bi, b := range blocks {
		records, err := stateDomainChangeBinaryAccessorV6ReadBlock(r, uint64(len(data)), h, b, uint32(bi*128))
		if err != nil {
			return nil, audit, err
		}
		for _, record := range records {
			if len(record.key) < 21 {
				eligible = false
				continue
			}
			var owner [20]byte
			copy(owner[:], record.key[1:21])
			seen[owner] |= 1 << record.key[0]
			if record.key[0] == 1 {
				audit.AccountKeys++
			}
			if len(record.key) >= 31 && record.key[0] == 2 && binary.BigEndian.Uint16(record.key[29:31]) == 515 {
				audit.AssetKeys++
			}
		}
	}
	for _, mask := range seen {
		if mask&2 != 0 && mask&4 != 0 {
			audit.CrossFlatOwners++
		}
	}
	var table *historyOwnerTable
	if eligible {
		owners := make([][20]byte, 0, len(seen))
		for owner := range seen {
			owners = append(owners, owner)
		}
		table, err = makeHistoryOwnerTable(owners)
		if err != nil {
			return nil, audit, err
		}
	}
	audit.Owners = uint64(len(seen))
	var keys bytes.Buffer
	var targetBlocks []stateDomainChangeBinaryAccessorV6Block
	largest := 0
	for bi, b := range blocks {
		records, err := stateDomainChangeBinaryAccessorV6ReadBlock(r, uint64(len(data)), h, b, uint32(bi*128))
		if err != nil {
			return nil, audit, err
		}
		list := make([]stateDomainChangeBinaryAccessorV6Key, len(records))
		for i, rec := range records {
			list[i] = stateDomainChangeBinaryAccessorV6Key{key: rec.key, keyID: rec.keyID, postingCount: rec.postings, postingOff: rec.postingOff, inlinePosting: rec.inlinePosting}
			audit.Records += uint64(rec.postings)
		}
		audit.Keys += uint64(len(records))
		if table == nil {
			continue
		}
		raw, stored, flags, err := encodeHistoryOwnerKeyBlock(list, h.fromTxNum, table, &largest)
		if err != nil {
			return nil, audit, err
		}
		if raw[0] == 1 {
			audit.CompactPages++
		} else {
			audit.PlainPages++
		}
		targetBlocks = append(targetBlocks, stateDomainChangeBinaryAccessorV6Block{firstKey: append([]byte(nil), b.firstKey...), dataOff: uint64(keys.Len()), dataLen: flags, rawLen: uint32(len(raw)), checksum: crc32.ChecksumIEEE(raw), keyCount: b.keyCount})
		keys.Write(stored)
	}
	if audit.Keys != h.keyCount || audit.Records != h.recordCount {
		return nil, audit, fmt.Errorf("source key/record count mismatch")
	}
	audit.SourceBytes = uint64(len(data))
	audit.SourceKeyBytes = h.keyDataLen
	audit.PostingBytes = h.postingLen
	audit.OffsetBytes = uint64(len(data)) - h.offsetDataBase
	audit.DirectoryBytes = h.blockDirLen
	audit.DictionaryDigest = h.dictionaryDigest
	if table == nil || uint64(keys.Len())+table.size() >= h.keyDataLen {
		audit.CandidateBytes = audit.SourceBytes
		audit.CandidateKeyBytes = h.keyDataLen
		audit.Version = 9
		audit.PlainPages = h.blockCount
		audit.CompactPages = 0
		return append([]byte(nil), data...), audit, nil
	}
	sparse := encodeHistoryAccessorSparseDirectory(targetBlocks)
	dirLen := uint64(len(targetBlocks))*8 + uint64(len(sparse))
	for _, b := range targetBlocks {
		dirLen += 2 + uint64(len(b.firstKey)) + stateDomainChangeBinaryAccessorV6BlockTail
	}
	if dirLen != h.blockDirLen {
		return nil, audit, fmt.Errorf("directory identity changed")
	}
	out := bytes.NewBuffer(make([]byte, 0, len(data)))
	header := append([]byte(nil), data[:120]...)
	binary.BigEndian.PutUint32(header[8:12], 10)
	binary.BigEndian.PutUint64(header[64:72], uint64(keys.Len()))
	binary.BigEndian.PutUint32(header[112:116], stateDomainChangeAccessorHeaderCRC(header, 10))
	out.Write(header)
	off := uint64(120 + len(targetBlocks)*8)
	for _, b := range targetBlocks {
		binary.Write(out, binary.BigEndian, off)
		off += 2 + uint64(len(b.firstKey)) + stateDomainChangeBinaryAccessorV6BlockTail
	}
	keyBase := uint64(120) + dirLen
	for _, b := range targetBlocks {
		binary.Write(out, binary.BigEndian, uint16(len(b.firstKey)))
		out.Write(b.firstKey)
		var tail [28]byte
		binary.BigEndian.PutUint64(tail[:8], keyBase+b.dataOff)
		binary.BigEndian.PutUint32(tail[8:12], b.dataLen)
		binary.BigEndian.PutUint32(tail[12:16], b.rawLen)
		binary.BigEndian.PutUint32(tail[16:20], b.checksum)
		binary.BigEndian.PutUint32(tail[20:24], b.keyCount)
		binary.BigEndian.PutUint32(tail[24:], crc32.Update(crc32.ChecksumIEEE(b.firstKey), crc32.IEEETable, tail[:24]))
		out.Write(tail[:])
	}
	out.Write(sparse)
	out.Write(keys.Bytes())
	// Key-data relocation leaves both complete V9 sections and their CRCs intact.
	postingStart := h.headerSize + h.blockDirLen + h.keyDataLen
	out.Write(data[postingStart:])
	if err := table.appendTo(out, uint64(out.Len())); err != nil {
		return nil, audit, err
	}
	candidate := out.Bytes()
	nr := bytes.NewReader(candidate)
	nh, err := decodeStateDomainChangeBinaryAccessorKeyHeader(nr, uint64(len(candidate)))
	if err != nil {
		return nil, audit, err
	}
	if nh.dictionaryDigest != h.dictionaryDigest {
		return nil, audit, fmt.Errorf("dictionary identity changed")
	}
	if err := checkHistoryOwnerDictionary(nr, nh); err != nil {
		return nil, audit, err
	}
	nb, err := stateDomainChangeBinaryAccessorV6ReadBlockDirectory(nr, nh)
	if err != nil {
		return nil, audit, err
	}
	digest := sha256.New()
	for bi, b := range blocks {
		source, err := stateDomainChangeBinaryAccessorV6ReadBlock(r, uint64(len(data)), h, b, uint32(bi*128))
		if err != nil {
			return nil, audit, err
		}
		target, err := stateDomainChangeBinaryAccessorV6ReadBlock(nr, uint64(len(candidate)), nh, nb[bi], uint32(bi*128))
		if err != nil {
			return nil, audit, err
		}
		if len(source) != len(target) {
			return nil, audit, fmt.Errorf("key-page count changed")
		}
		for i, a := range source {
			z := target[i]
			if !bytes.Equal(a.key, z.key) || a.keyID != z.keyID || a.postings != z.postings || a.postingOff != z.postingOff || a.inline != z.inline || a.inlinePosting != z.inlinePosting {
				return nil, audit, fmt.Errorf("expanded key/ID/metadata changed at page %d", bi)
			}
		}
		for _, rec := range target {
			var length [4]byte
			binary.BigEndian.PutUint32(length[:], uint32(len(rec.key)))
			digest.Write(length[:])
			digest.Write(rec.key)
		}
	}
	// The production dictionary commitment uses fixed uint32 lengths.
	if !bytes.Equal(digest.Sum(nil), h.dictionaryDigest[:]) {
		return nil, audit, fmt.Errorf("expanded dictionary digest mismatch")
	}
	candidatePosting := nh.headerSize + nh.blockDirLen + nh.keyDataLen
	if !bytes.Equal(data[postingStart:], candidate[candidatePosting:nh.owners.prefixSize]) {
		return nil, audit, fmt.Errorf("posting/locator bytes changed")
	}
	audit.CandidateBytes = uint64(len(candidate))
	audit.CandidateKeyBytes = nh.keyDataLen
	audit.OwnerDataBytes = uint64(len(table.data))
	audit.OwnerDirectoryBytes = uint64(len(table.directory))
	audit.OwnerFooterBytes = 64
	audit.Version = 10
	return candidate, audit, nil
}

func TestHistoryOwnerOfflineTransformMatchesBuilder(t *testing.T) {
	old, _ := buildOwnerAccessorFixture(t, 9, 4200, true)
